insert into questions (id, exam, topic_id, status, difficulty, stem, lead_in, tags) values
('d7000000-0000-0000-0000-000000000001', 'mrcp2', 'fedc0e81-de96-4885-a894-a0f6389f3996',
insert into question_options (question_id, label, option_text, is_correct, rationale, sort_order) values
('d7000000-0000-0000-0000-000000000001', 'A', 'It better predicts overall vancomycin exposure and correlates more closely with both efficacy and nephrotoxicity than a single trough level', true, 'Correct. AUC/MIC ratio is the pharmacokinetic-pharmacodynamic index that best predicts vancomycin efficacy against MRSA, and trough concentrations correlate poorly with AUC, particularly at extremes of renal function or with unusual dosing intervals such as intermittent haemodialysis. AUC-guided (typically Bayesian) dosing targets an AUC24/MIC of 400-600, achieving comparable or better outcomes while reducing nephrotoxicity compared with targeting a trough of 15-20 mg/L.', 1),
('d7000000-0000-0000-0000-000000000001', 'B', 'It removes the need for any further vancomycin level monitoring once the initial AUC is calculated', false, 'Ruled out because ongoing monitoring is still required as renal function, dialysis clearance and clinical status change, particularly in a haemodialysis-dependent patient whose vancomycin clearance is closely tied to the dialysis schedule.', 2),
('d7000000-0000-0000-0000-000000000001', 'C', 'It allows a lower vancomycin trough target of 5-10 mg/L to be used safely in prosthetic valve endocarditis', false, 'Ruled out because AUC-guided dosing does not simply permit a lower trough target; the AUC target itself (400-600 mg·h/L) is what is optimised, and for endocarditis with a deep-seated prosthetic focus adequate exposure remains essential regardless of monitoring method.', 3),
('d7000000-0000-0000-0000-000000000001', 'D', 'It eliminates the risk of vancomycin-induced nephrotoxicity entirely', false, 'Ruled out because AUC-guided dosing reduces but does not eliminate nephrotoxicity risk; this patient is already anuric/dialysis-dependent, and other nephrotoxins and haemodynamic factors remain relevant to overall renal risk assessment more broadly.', 4),
('d7000000-0000-0000-0000-000000000001', 'E', 'It allows vancomycin to be safely switched to oral therapy for this indication', false, 'Ruled out because oral vancomycin is not systemically absorbed and has no role in bacteraemia or endocarditis; AUC-guided dosing pertains to intravenous vancomycin exposure, not route of administration.', 5),
('d7000000-0000-0000-0000-000000000002', 'A', 'Treat with vancomycin plus gentamicin as first-line therapy without further allergy assessment', false, 'Ruled out because avoiding beta-lactams unnecessarily exposes the patient to inferior efficacy and more toxic alternatives (nephrotoxicity, ototoxicity) when the allergy history is low-risk and readily clarified; unverified allergy labels should be actively challenged, not simply worked around.', 1),
('d7000000-0000-0000-0000-000000000002', 'B', 'Avoid all beta-lactams indefinitely given any history of penicillin-associated rash', false, 'Ruled out because a remote, mild, non-immediate rash does not represent a true contraindication to future beta-lactam use, and blanket avoidance leads to worse clinical outcomes and greater antimicrobial resistance pressure from broad-spectrum alternatives.', 2),
('d7000000-0000-0000-0000-000000000002', 'C', 'Refer for allergy assessment with a view to a supervised graded oral challenge or skin testing to de-label the allergy', true, 'Correct. The history described (a mild, non-immediate maculopapular rash in childhood, no anaphylaxis, angioedema, or severe cutaneous adverse reaction features) is low-risk and the great majority of such labels are inaccurate. Formal allergy assessment with skin testing and/or a supervised graded challenge can safely de-label most such patients, allowing first-line beta-lactam therapy, which is particularly important for endocarditis where penicillin-based regimens have superior outcomes to alternatives.', 3),
('d7000000-0000-0000-0000-000000000002', 'D', 'Proceed directly to rapid intravenous penicillin desensitisation on the ward without allergy assessment', false, 'Ruled out because desensitisation is reserved for patients with a genuine, higher-risk allergy history where no alternative exists and skin testing is unhelpful or unavailable; for a low-risk history like this, de-labelling via assessment/challenge is more appropriate than the resource-intensive desensitisation process.', 4),
('d7000000-0000-0000-0000-000000000002', 'E', 'Substitute doxycycline for the definitive endocarditis regimen to avoid any beta-lactam exposure', false, 'Ruled out because doxycycline is not an appropriate first-line or bactericidal agent for streptococcal endocarditis, and this approach unnecessarily forgoes optimal therapy based on an unclarified allergy label.', 5),
('d7000000-0000-0000-0000-000000000003', 'A', 'Oral fluconazole as first-line therapy given normal renal function', false, 'Ruled out because fluconazole is not recommended as first-line therapy in critically ill or haemodynamically unstable patients with candidaemia; it may be considered for step-down therapy once the patient is stable and the isolate is confirmed fluconazole-susceptible, but not as the initial choice here.', 1),
('d7000000-0000-0000-0000-000000000003', 'B', 'An echinocandin (e.g. micafungin or caspofungin) as first-line empirical and initial definitive therapy', true, 'Correct. Guidelines recommend an echinocandin as first-line therapy for candidaemia in most adult patients, particularly those who are critically ill, haemodynamically unstable, or have had recent azole exposure, because of rapid fungicidal activity and a low resistance rate against Candida albicans compared with fluconazole. Central line removal (source control) is also essential and has already been performed.', 2),
('d7000000-0000-0000-0000-000000000003', 'C', 'Continue TPN unchanged and treat with topical antifungal mouthwash only', false, 'Ruled out because candidaemia is an invasive bloodstream infection requiring systemic antifungal therapy and source control (line removal), not topical treatment; TPN and any remaining infected devices should be addressed as part of source control.', 3),
('d7000000-0000-0000-0000-000000000003', 'D', 'Amphotericin B deoxycholate as first-line therapy in preference to an echinocandin', false, 'Ruled out because conventional amphotericin B deoxycholate has greater toxicity (nephrotoxicity, infusion reactions) than an echinocandin and is not preferred first-line when an echinocandin is available and there is no specific indication (e.g. proven resistance, CNS/ocular involvement) favouring amphotericin.', 4),
('d7000000-0000-0000-0000-000000000003', 'E', 'Withhold antifungal therapy until formal susceptibility testing results are available', false, 'Ruled out because empirical antifungal therapy should be started promptly once candidaemia is identified, given the high mortality associated with delayed treatment; therapy is later refined according to susceptibility results, not delayed until they return.', 5),
('d7000000-0000-0000-0000-000000000004', 'A', 'Continue daily intravenous flucloxacillin as an inpatient for the full six-week course', false, 'Ruled out because prolonged unnecessary inpatient admission is not required when a suitable alternative exists; this increases healthcare-associated infection risk, cost, and is not patient-centred when a long-acting option can safely complete therapy.', 1),
('d7000000-0000-0000-0000-000000000004', 'B', 'Switch to oral flucloxacillin monotherapy without dose optimisation for bone penetration', false, 'Ruled out because while oral step-down (e.g. with an agent selected for good bone penetration and adequate dosing) can be appropriate in some patients, the vignette specifically highlights the absence of OPAT support and difficult access as the barrier, making a long-acting parenteral option the most directly suited answer; oral flucloxacillin also has relatively poor bioavailability limiting its suitability as sole step-down therapy for osteomyelitis.', 2),
('d7000000-0000-0000-0000-000000000004', 'C', 'Discontinue antibiotics now since two weeks of intravenous therapy is sufficient for osteomyelitis', false, 'Ruled out because osteomyelitis typically requires substantially longer treatment courses (commonly around six weeks) than two weeks, particularly without surgical debridement/curative resection, and premature discontinuation risks relapse.', 3),
('d7000000-0000-0000-0000-000000000004', 'D', 'Insert a peripherally inserted central catheter (PICC) and rely on the patient for self-administration of daily intravenous antibiotics without any support', false, 'Ruled out because self-administration of intravenous antibiotics without appropriate training, support or a safety net is unsafe, especially in a patient with difficult access and no local OPAT nursing service to support this approach.', 4),
('d7000000-0000-0000-0000-000000000004', 'E', 'Switch to a long-acting lipoglycopeptide such as dalbavancin, given as one or two doses to cover the remaining treatment course', true, 'Correct. Long-acting lipoglycopeptides such as dalbavancin (with a half-life of around two weeks) can be used to complete extended courses of therapy for Gram-positive bone and joint infections with only one or two infusions, avoiding the need for daily line access or nursing visits, and are particularly useful where conventional OPAT infrastructure is unavailable or venous access is difficult.', 5),
('d7000000-0000-0000-0000-000000000005', 'A', 'A trough level taken immediately before the next dose, targeting a level below 2 mg/L, exactly as with multiple-daily dosing', false, 'Ruled out because peak/trough monitoring is used for traditional multiple-daily-dose aminoglycoside regimens, not extended-interval once-daily dosing, which uses a differently timed level interpreted via a nomogram.', 1),
('d7000000-0000-0000-0000-000000000005', 'B', 'A peak level taken 30 minutes after completion of the infusion only, with no further monitoring required', false, 'Ruled out because while a peak may sometimes be checked for efficacy purposes in select scenarios, routine extended-interval dosing is monitored predominantly via a nomogram-timed random level to guide the interval, and ongoing monitoring (renal function, further levels) continues through treatment, not a single isolated peak check.', 2),
('d7000000-0000-0000-0000-000000000005', 'C', 'No level is required if renal function is normal at baseline', false, 'Ruled out because renal function can change during treatment (aminoglycosides are nephrotoxic) and monitoring is required throughout a course, particularly beyond 48-72 hours of treatment, regardless of a normal baseline creatinine clearance.', 3),
('d7000000-0000-0000-0000-000000000005', 'D', 'A random level timed according to a validated nomogram (e.g. Hartford nomogram), typically 6-14 hours after the dose, to determine the next dosing interval', true, $x$Correct. Extended-interval aminoglycoside dosing is monitored using a single random level taken at a defined time post-dose (commonly 6-14 hours), plotted against a validated nomogram such as the Hartford nomogram, which determines whether the standard 24-hourly interval is appropriate or should be extended (e.g. to 36 or 48 hours) based on the patient's clearance. This differs from traditional peak-and-trough monitoring used with multiple-daily-dose regimens.$x$, 4),
('d7000000-0000-0000-0000-000000000005', 'E', 'A level taken immediately at the end of the infusion to assess for ototoxicity risk', false, 'Ruled out because ototoxicity is not assessed via a serum level taken at end of infusion; monitoring uses nomogram-timed levels to guide dosing interval and cumulative exposure, with clinical/audiometric assessment used separately if ototoxicity is clinically suspected.', 5),
('d7000000-0000-0000-0000-000000000006', 'A', 'Meropenem at standard dose, since Klebsiella pneumoniae is usually carbapenem-susceptible', false, 'Ruled out because susceptibility testing has already confirmed carbapenem resistance with confirmed KPC production; using a carbapenem to which the organism is resistant would be inappropriate and ineffective.', 1),
('d7000000-0000-0000-0000-000000000006', 'B', 'Extended-infusion meropenem alone regardless of the confirmed resistance mechanism', false, 'Ruled out because although extended-infusion carbapenem dosing can sometimes be used for organisms with borderline elevated MICs, a confirmed carbapenemase producer with resistance on testing is not reliably treated by extended infusion of a drug the organism inactivates.', 2),
('d7000000-0000-0000-0000-000000000006', 'C', 'Ceftazidime-avibactam', true, 'Correct. Avibactam is a non-beta-lactam beta-lactamase inhibitor that restores activity against KPC (class A serine carbapenemase)-producing organisms when combined with ceftazidime, making ceftazidime-avibactam a preferred option for confirmed KPC-producing Enterobacteriaceae bacteraemia. It is not active against metallo-beta-lactamases (e.g. NDM), which would require a different combination such as aztreonam-avibactam.', 3),
('d7000000-0000-0000-0000-000000000006', 'D', 'Colistin monotherapy as the preferred first-line option given its historical role against carbapenem-resistant organisms', false, 'Ruled out because colistin carries significant nephrotoxicity, has less reliable pharmacokinetics, and newer beta-lactamase inhibitor combinations such as ceftazidime-avibactam have demonstrated better efficacy and lower toxicity, making them preferred over colistin where the organism (and mechanism) is susceptible.', 4),
('d7000000-0000-0000-0000-000000000006', 'E', 'Piperacillin-tazobactam at high dose, since tazobactam also inhibits beta-lactamases', false, 'Ruled out because tazobactam does not reliably inhibit KPC-type serine carbapenemases at achievable concentrations, and piperacillin-tazobactam is not an appropriate agent for treating a confirmed KPC-producing organism.', 5),
('d7000000-0000-0000-0000-000000000007', 'A', 'The patient is a CYP2C19 ultra-rapid metaboliser and no drug interaction is relevant here', false, 'Ruled out because although CYP2C19 genetic polymorphism does affect voriconazole metabolism and levels, the clinical scenario specifically introduces a new potent enzyme-inducing drug (rifampicin), which is the much more likely and clinically significant explanation requiring action, rather than attributing this solely to pharmacogenomics without addressing the interaction.', 1),
('d7000000-0000-0000-0000-000000000007', 'B', 'Voriconazole levels are unaffected by concomitant medications and the low level indicates poor absorption requiring a switch to intravenous administration only', false, 'Ruled out because voriconazole is well known for numerous clinically significant drug interactions via CYP450 pathways; attributing the low level purely to absorption ignores the well-recognised and highly relevant interaction with rifampicin.', 2),
('d7000000-0000-0000-0000-000000000007', 'C', 'No action is needed as voriconazole trough levels do not need to be therapeutic for efficacy in invasive aspergillosis', false, 'Ruled out because voriconazole exhibits a narrow therapeutic index with a well-established exposure-response relationship in invasive aspergillosis; sub-therapeutic levels are associated with treatment failure and levels should be actively monitored and optimised.', 3),
('d7000000-0000-0000-0000-000000000007', 'D', 'Rifampicin induces CYP450 enzymes that metabolise voriconazole, substantially reducing its levels; rifampicin and voriconazole should not be co-administered and an alternative agent should be used', true, 'Correct. Rifampicin is a potent inducer of CYP3A4 (and other CYP enzymes involved in voriconazole metabolism), which markedly reduces voriconazole plasma concentrations and can lead to treatment failure of invasive fungal infection. Concomitant use is contraindicated; an alternative antimycobacterial agent with less enzyme induction (e.g. avoiding rifampicin) or an alternative antifungal not affected by this interaction (such as an echinocandin or liposomal amphotericin B, noting azole cross-reactivity issues) should be considered in discussion with specialists.', 4),
('d7000000-0000-0000-0000-000000000007', 'E', 'Increase the voriconazole dose substantially while continuing rifampicin unchanged', false, 'Ruled out because the magnitude of CYP induction by rifampicin is such that adequate voriconazole exposure typically cannot be reliably achieved even with dose increases, and continuing the combination risks unpredictable toxicity or continued subtherapeutic levels; the interaction is generally considered a contraindication rather than something to dose around.', 5),
('d7000000-0000-0000-0000-000000000008', 'A', 'A further standard 10-day course of oral vancomycin at the same dose as before', false, 'Ruled out because repeating the same regimen that has already failed to prevent recurrence twice is unlikely to succeed a third time; guidelines recommend escalating to a strategy specifically aimed at reducing recurrence risk, such as microbiota restoration therapy or a vancomycin taper/pulse regimen with adjunctive options.', 1),
('d7000000-0000-0000-0000-000000000008', 'B', 'Oral metronidazole as first-line therapy for this recurrence', false, 'Ruled out because metronidazole is inferior to vancomycin or fidaxomicin for C. difficile infection and is not recommended, particularly for recurrent disease; it is reserved for situations where other agents are unavailable.', 2),
('d7000000-0000-0000-0000-000000000008', 'C', 'Total colectomy as the next step given recurrent disease', false, 'Ruled out because colectomy is reserved for fulminant, life-threatening C. difficile colitis with complications such as toxic megacolon, perforation or refractory septic shock, not for recurrent but otherwise uncomplicated disease; less invasive, microbiota-directed options should be tried first.', 3),
('d7000000-0000-0000-0000-000000000008', 'D', 'Long-term prophylactic oral vancomycin indefinitely without addressing the underlying recurrence risk', false, 'Ruled out because indefinite antibiotic prophylaxis is not an appropriate long-term strategy for recurrent C. difficile infection and does not restore normal colonic microbiota; targeted interventions (e.g. faecal microbiota transplantation, or fidaxomicin/bezlotoxumab-based strategies) address the underlying recurrence risk more effectively.', 4),
('d7000000-0000-0000-0000-000000000008', 'E', 'Faecal microbiota transplantation (or an alternative microbiota restoration therapy), given multiple prior recurrences', true, 'Correct. For patients with multiple recurrent episodes of C. difficile infection (typically after a second recurrence, i.e. third episode overall), faecal microbiota transplantation is recommended, as it has substantially higher efficacy in preventing further recurrence than repeated antibiotic courses by restoring normal gut microbial diversity and colonisation resistance.', 5),
('d7000000-0000-0000-0000-000000000009', 'A', 'Rapid intravenous or oral penicillin desensitisation under monitored conditions, followed immediately by the required treatment course', true, 'Correct. Where a confirmed, IgE-mediated (type I) penicillin allergy exists and penicillin is the only effective agent for the specific condition (as in neurosyphilis, where alternatives are inferior and not well validated), desensitisation is indicated. This involves administering gradually increasing doses of penicillin over several hours under close monitoring in a setting equipped to manage anaphylaxis, temporarily inducing tolerance so that the definitive course can then be given without interruption.', 1),
('d7000000-0000-0000-0000-000000000009', 'B', 'Treat with doxycycline as an equally effective alternative to penicillin for neurosyphilis', false, 'Ruled out because doxycycline is not an established equally effective first-line alternative for neurosyphilis, particularly in the context of HIV co-infection where penicillin remains the treatment of choice with the strongest evidence base.', 2),
('d7000000-0000-0000-0000-000000000009', 'C', 'Avoid any penicillin exposure and treat empirically with high-dose ceftriaxone alone without addressing the confirmed allergy', false, 'Ruled out because while ceftriaxone has some cross-reactivity considerations and is sometimes used as an alternative, in a patient with confirmed severe IgE-mediated penicillin allergy where penicillin is preferred, desensitisation to enable optimal first-line treatment is the more robust, guideline-supported approach, particularly given the seriousness of neurosyphilis in an HIV-positive patient.', 3),
('d7000000-0000-0000-0000-000000000009', 'D', 'Administer a standard dose of penicillin under observation, since prior skin testing confirms the diagnosis but treatment can proceed as normal', false, 'Ruled out because a confirmed positive skin test to penicillin indicates genuine risk of anaphylaxis on re-exposure; a standard dose should not be given without desensitisation, which specifically and gradually induces temporary tolerance to allow safe administration.', 4),
('d7000000-0000-0000-0000-000000000009', 'E', 'Refer for allergy de-labelling via a graded oral challenge in an outpatient clinic before starting treatment', false, 'Ruled out because graded challenge/de-labelling is appropriate for low-risk, unconfirmed allergy histories, not for a patient with a confirmed anaphylactic reaction and positive skin testing; in this high-risk, confirmed-allergy scenario, formal desensitisation immediately prior to necessary treatment is the correct approach rather than attempting to disprove the allergy.', 5),
('d7000000-0000-0000-0000-000000000010', 'A', 'Linezolid should be avoided in this patient purely because of his thrombocytopenia, which is an absolute contraindication', false, 'Ruled out because although linezolid can cause or worsen thrombocytopenia (particularly with courses beyond 2 weeks), pre-existing sepsis-related thrombocytopenia is not an absolute contraindication; it warrants closer monitoring of platelet counts during treatment rather than automatic avoidance, especially when it may be the most suitable agent, whereas the serotonin syndrome interaction is the more immediately important prescribing safety issue to address before starting therapy.', 1),
('d7000000-0000-0000-0000-000000000010', 'B', 'Linezolid is a weak monoamine oxidase inhibitor and combined use with sertraline carries a significant risk of serotonin syndrome, requiring careful risk-benefit assessment and monitoring, or temporary substitution of the serotonergic agent if feasible', true, 'Correct. Linezolid has weak, reversible monoamine oxidase inhibitor activity, and its combination with serotonergic drugs (including SSRIs such as sertraline) carries a recognised risk of serotonin syndrome. This does not necessarily preclude linezolid use, particularly when it is the most appropriate antimicrobial choice, but requires careful assessment, discussion with the patient/prescriber regarding the antidepressant, and close monitoring for signs of serotonin toxicity (agitation, clonus, hyperreflexia, autonomic instability) if the combination proceeds.', 2),
('d7000000-0000-0000-0000-000000000010', 'C', 'There is no clinically relevant interaction between linezolid and sertraline, so both may be continued without any additional monitoring', false, 'Ruled out because this significantly understates a recognised and potentially serious drug interaction; concomitant use requires explicit risk assessment and monitoring, not an assumption of safety.', 3),
('d7000000-0000-0000-0000-000000000010', 'D', 'Linezolid is renally cleared and therefore requires the same dose-adjustment and monitoring as vancomycin in renal impairment', false, 'Ruled out because linezolid is primarily metabolised via non-renal (oxidative) pathways and generally does not require dose adjustment for renal impairment, which is actually one of its practical advantages over vancomycin in a patient with deteriorating renal function; this makes the statement factually incorrect as a reason to avoid the switch.', 4),
('d7000000-0000-0000-0000-000000000010', 'E', 'Linezolid should only be given intravenously and cannot be used for step-down oral therapy in this scenario', false, $x$Ruled out because linezolid has excellent oral bioavailability and is frequently used for effective intravenous-to-oral switch therapy, which is one of its clinical advantages relevant to this patient's future step-down plan.$x$, 5),
('d7000000-0000-0000-0000-000000000011', 'A', 'Defer antiretroviral therapy until TB treatment is complete (approximately 6 months) to avoid any risk of IRIS', false, 'Ruled out because deferring ART for the full duration of TB treatment in a patient with a CD4 count this low significantly increases mortality risk from HIV-related complications; early ART is specifically recommended in this very immunosuppressed group despite IRIS risk.', 1),
('d7000000-0000-0000-0000-000000000011', 'B', 'Defer antiretroviral therapy until 8-12 weeks after starting TB treatment regardless of CD4 count', false, 'Ruled out because the 8-12 week deferral strategy applies to patients with higher CD4 counts (generally above 50 cells/microL); for CD4 counts below 50 cells/microL, earlier initiation (around 2 weeks) is recommended due to the mortality benefit outweighing IRIS risk.', 2),
('d7000000-0000-0000-0000-000000000011', 'C', 'Start antiretroviral therapy within 2 weeks of starting TB treatment, given the very low CD4 count', true, 'Correct. In patients with advanced HIV (CD4 count under 50 cells/microL) and tuberculosis co-infection, early ART initiation (within approximately 2 weeks of starting TB treatment) has been shown to reduce mortality, despite an increased risk of TB-associated immune reconstitution inflammatory syndrome (IRIS), because the mortality benefit of early ART outweighs the risks of IRIS in this very immunosuppressed group. This contrasts with patients with higher CD4 counts, where ART can be deferred to around 8-12 weeks to reduce IRIS risk, except in TB meningitis where earlier ART increases mortality due to CNS IRIS.', 3),
('d7000000-0000-0000-0000-000000000011', 'D', 'Start antiretroviral therapy and TB treatment simultaneously on the same day', false, 'Ruled out because even in patients with very low CD4 counts, a short delay (about 2 weeks) after starting TB treatment is recommended rather than same-day co-initiation, allowing initial stabilisation on TB therapy and reducing the risk of overwhelming paradoxical inflammatory reactions.', 4),
('d7000000-0000-0000-0000-000000000011', 'E', 'Withhold antiretroviral therapy entirely until the CD4 count rises above 200 cells/microL on TB treatment alone', false, 'Ruled out because ART is required to achieve CD4 recovery in the first place; withholding ART until CD4 rises without treatment is not a valid strategy and would leave the patient at ongoing high risk of further opportunistic disease and death.', 5),
('d7000000-0000-0000-0000-000000000012', 'A', 'Start antiretroviral therapy within 2 weeks, as with other opportunistic infections at very low CD4 counts', false, $x$Ruled out because cryptococcal meningitis is a specific and important exception to the 'early ART' rule that applies to other opportunistic infections; early ART here significantly increases mortality via IRIS-related complications.$x$, 1),
('d7000000-0000-0000-0000-000000000012', 'B', 'Start antiretroviral therapy simultaneously with antifungal induction therapy on the same day', false, 'Ruled out because simultaneous initiation would markedly increase the risk of early, severe cryptococcal IRIS with raised intracranial pressure and is specifically associated with worse outcomes in trial data.', 2),
('d7000000-0000-0000-0000-000000000012', 'C', 'Withhold antiretroviral therapy indefinitely until the cryptococcal antigen titre becomes fully negative', false, 'Ruled out because ART should not be withheld indefinitely; guidance is based on a defined time interval (around 4-6 weeks) after antifungal induction rather than requiring antigen clearance, which can take much longer and is not itself the trigger for ART timing.', 3),
('d7000000-0000-0000-0000-000000000012', 'D', 'The timing of antiretroviral therapy makes no difference to outcomes in cryptococcal meningitis', false, 'Ruled out because trial evidence has specifically demonstrated a mortality difference according to ART timing in this condition, making timing a clinically important and tested decision point.', 4),
('d7000000-0000-0000-0000-000000000012', 'E', 'Delay antiretroviral therapy until approximately 4-6 weeks after starting antifungal induction therapy', true, 'Correct. Unlike most other opportunistic infections, early ART initiation in cryptococcal meningitis is associated with increased mortality, largely due to cryptococcal-associated IRIS, which can cause life-threatening cerebral oedema and raised intracranial pressure. Current guidelines recommend deferring ART until approximately 4-6 weeks after starting antifungal therapy, once the cryptococcal burden has been substantially reduced, based on evidence from trials such as COAT.', 5),
('d7000000-0000-0000-0000-000000000013', 'A', 'Proceed directly to stereotactic brain biopsy before starting any treatment', false, 'Ruled out because biopsy is invasive and carries procedural risk; it is reserved for patients who fail to respond to an empirical trial of anti-toxoplasma therapy or where the clinical/radiological picture is atypical for toxoplasmosis, not as the routine first step.', 1),
('d7000000-0000-0000-0000-000000000013', 'B', 'Start whole-brain radiotherapy empirically for presumed primary CNS lymphoma', false, 'Ruled out because primary CNS lymphoma is a less likely initial diagnosis than toxoplasmosis in a seropositive patient with typical multiple ring-enhancing lesions, and empirical treatment for toxoplasmosis with clinical/radiological reassessment is the appropriate first step before considering lymphoma-directed therapy.', 2),
('d7000000-0000-0000-0000-000000000013', 'C', 'Start high-dose corticosteroids alone as the primary treatment without anti-toxoplasma therapy', false, 'Ruled out because corticosteroids alone do not treat the underlying infective process and can complicate later interpretation of response to anti-toxoplasma therapy and any subsequent biopsy (by reducing lymphoma cell burden if that were the true diagnosis); steroids are used adjunctively for mass effect only when clearly indicated, not as monotherapy.', 3),
('d7000000-0000-0000-0000-000000000013', 'D', 'Start empirical anti-toxoplasma therapy (e.g. pyrimethamine, sulfadiazine and folinic acid) and reassess with repeat imaging in 10-14 days', true, 'Correct. In an HIV patient with a low CD4 count, positive toxoplasma serology and typical ring-enhancing CNS lesions, empirical anti-toxoplasma treatment is the standard first step rather than immediate brain biopsy, because toxoplasmosis is by far the most likely diagnosis in this setting. Clinical and radiological improvement is expected within 10-14 days; failure to respond raises the possibility of an alternative diagnosis, particularly primary CNS lymphoma, and prompts further investigation (e.g. brain biopsy, EBV PCR in CSF, or SPECT/PET imaging).', 4),
('d7000000-0000-0000-0000-000000000013', 'E', 'Delay any treatment until antiretroviral therapy has been established and CD4 count has recovered', false, 'Ruled out because active CNS toxoplasmosis is an acute, life-threatening infection requiring prompt treatment; delaying treatment while awaiting immune recovery via ART (which itself should be deferred appropriately after starting toxoplasma treatment) would risk further neurological deterioration.', 5),
('d7000000-0000-0000-0000-000000000014', 'A', 'Manage conservatively with observation alone, as CMV retinitis typically resolves spontaneously once CD4 count improves', false, 'Ruled out because untreated CMV retinitis progresses and can cause irreversible vision loss or retinal detachment; specific antiviral treatment is required promptly, not observation alone.', 1),
('d7000000-0000-0000-0000-000000000014', 'B', 'Start systemic anti-CMV therapy (e.g. oral valganciclovir, or intravenous ganciclovir/intravitreal therapy for sight-threatening disease), with urgent ophthalmology involvement, and initiate antiretroviral therapy after a short interval to reduce IRIS-related uveitis risk', true, 'Correct. CMV retinitis requires prompt systemic anti-CMV therapy to prevent further visual loss, with the choice and route (oral valganciclovir vs intravenous ganciclovir plus/minus intravitreal therapy) depending on lesion location and severity; urgent ophthalmology input is essential given the risk of retinal detachment and permanent vision loss. Antiretroviral therapy should be started, generally within 2 weeks, but with awareness that CMV-associated immune recovery uveitis can occur as an IRIS phenomenon during immune reconstitution.', 2),
('d7000000-0000-0000-0000-000000000014', 'C', 'Start antiretroviral therapy alone without any CMV-specific antiviral treatment, as immune reconstitution will clear the infection', false, 'Ruled out because relying on ART alone risks ongoing retinal damage before adequate immune recovery occurs, and can precipitate immune recovery uveitis without concurrent antiviral control of CMV; specific anti-CMV therapy is required.', 3),
('d7000000-0000-0000-0000-000000000014', 'D', 'Treat with oral aciclovir as first-line therapy for CMV retinitis', false, 'Ruled out because aciclovir has minimal activity against CMV and is not an appropriate treatment; agents such as (val)ganciclovir, foscarnet or cidofovir are used for CMV disease.', 4),
('d7000000-0000-0000-0000-000000000014', 'E', 'Defer any treatment until formal CMV PCR viral load quantification from vitreous fluid is obtained', false, 'Ruled out because CMV retinitis is typically diagnosed clinically by its characteristic fundoscopic appearance in the context of advanced immunosuppression, and treatment should not be delayed awaiting invasive vitreous sampling, which is not routinely required before starting therapy.', 5),
('d7000000-0000-0000-0000-000000000015', 'A', 'Address adherence barriers directly with the patient, perform genotypic resistance testing while continuing the current regimen, and adjust therapy based on results and adherence support rather than switching blindly', true, 'Correct. The most common cause of virological failure is suboptimal adherence rather than true drug resistance; addressing this is essential. Genotypic resistance testing should be performed while the patient is still taking the failing regimen (as resistant mutations may become undetectable once selective drug pressure is removed), and any regimen change should be guided by the resistance results together with an adherence support plan, rather than an empirical switch.', 1),
('d7000000-0000-0000-0000-000000000015', 'B', 'Stop all antiretroviral therapy for 4 weeks before performing resistance testing, to allow accurate interpretation', false, 'Ruled out because stopping therapy allows wild-type virus to become dominant again, causing resistant variants to fall below the detection threshold of standard genotypic assays and giving falsely reassuring results; resistance testing should be performed while still on the failing regimen.', 2),
('d7000000-0000-0000-0000-000000000015', 'C', 'Switch empirically to a new three-drug regimen from a different class without waiting for resistance results', false, 'Ruled out because switching before resistance results are available risks selecting an inadequate regimen if unrecognised resistance mutations are present, and does not address the likely underlying adherence problem; results should guide any regimen change where possible.', 3),
('d7000000-0000-0000-0000-000000000015', 'D', $x$Increase the dose of the current regimen's protease inhibitor to overcome presumed resistance$x$, false, $x$Ruled out because empirically increasing a single drug's dose without characterising resistance and confirming adherence is not appropriate management of virological failure; therapy should be reviewed comprehensively, not adjusted in an untargeted way.$x$, 4),
('d7000000-0000-0000-0000-000000000015', 'E', 'Reassure the patient that a single viral load blip does not require any action or further testing', false, $x$Ruled out because a viral load of 8,400 copies/mL after prior sustained suppression represents confirmed virological failure rather than a transient low-level 'blip' (typically defined as a low-level, isolated detectable result that resuppresses spontaneously); this requires active evaluation, not reassurance alone.$x$, 5),
('d7000000-0000-0000-0000-000000000016', 'A', 'Stop dolutegravir and switch to an alternative agent unaffected by rifampicin, without dose adjustment options being available', false, 'Ruled out because dose adjustment (twice-daily dolutegravir) is a well-established and effective strategy that avoids an unnecessary regimen switch during TB treatment, which is preferred when adherence and tolerability allow it.', 1),
('d7000000-0000-0000-0000-000000000016', 'B', 'Increase dolutegravir to twice-daily dosing for the duration of concomitant rifampicin therapy, then revert to once-daily dosing after rifampicin is stopped', true, 'Correct. Rifampicin substantially induces UGT1A1 and reduces dolutegravir plasma concentrations. Rather than switching antiretroviral class, current guidance supports increasing dolutegravir to twice-daily dosing during concomitant rifampicin therapy to maintain adequate drug exposure, reverting to standard once-daily dosing once rifampicin is discontinued, while continuing the nucleoside backbone unchanged.', 2),
('d7000000-0000-0000-0000-000000000016', 'C', 'Continue dolutegravir once daily unchanged, as the interaction with rifampicin is not clinically significant', false, 'Ruled out because the interaction is clinically significant and can result in subtherapeutic dolutegravir levels and risk of virological failure if the dose is not increased during rifampicin co-administration.', 3),
('d7000000-0000-0000-0000-000000000016', 'D', 'Substitute rifabutin-based TB treatment for rifampicin as the only acceptable solution, since dolutegravir dosing cannot be adjusted', false, 'Ruled out because although rifabutin (a weaker CYP/UGT inducer) is sometimes used as an alternative to rifampicin in certain drug interaction scenarios, dolutegravir dose adjustment (twice daily) with continued rifampicin is an established, guideline-supported and often preferred option, making this not the most appropriate single answer.', 4),
('d7000000-0000-0000-0000-000000000016', 'E', 'Stop antiretroviral therapy completely until the TB treatment course is finished', false, 'Ruled out because stopping ART during TB treatment is not appropriate; TB/HIV co-treatment with appropriately adjusted ART is standard practice and interruption would risk HIV disease progression and resistance.', 5),
('d7000000-0000-0000-0000-000000000017', 'A', 'Corticosteroids are contraindicated in HIV-associated PCP due to the risk of worsening immunosuppression', false, 'Ruled out because adjunctive corticosteroids are specifically recommended (not contraindicated) in moderate-to-severe PCP, as the mortality/respiratory benefit from reducing treatment-related inflammatory lung injury outweighs concerns about transient additional immunosuppression during a short, tapering course.', 1),
('d7000000-0000-0000-0000-000000000017', 'B', 'Corticosteroids should be reserved only for patients who fail to respond to co-trimoxazole after one week', false, 'Ruled out because adjunctive corticosteroids should be started early (ideally within 72 hours) in patients who meet severity criteria at presentation, not delayed until treatment failure is apparent, since early administration is what confers the mortality benefit.', 2),
('d7000000-0000-0000-0000-000000000017', 'C', 'Nebulised pentamidine should replace co-trimoxazole as first-line therapy given the severity of hypoxaemia', false, 'Ruled out because nebulised pentamidine is not appropriate for treatment of established PCP (it has a role in prophylaxis in some settings); intravenous or oral co-trimoxazole remains first-line therapy for active disease, with alternative agents (e.g. intravenous pentamidine, clindamycin-primaquine) reserved for those unable to tolerate co-trimoxazole.', 3),
('d7000000-0000-0000-0000-000000000017', 'D', 'High-flow oxygen alone is sufficient and no other adjunctive treatment is required regardless of severity', false, 'Ruled out because supportive oxygen therapy alone does not address the underlying inflammatory component of severe PCP; adjunctive corticosteroids are an evidence-based addition to antimicrobial and supportive respiratory therapy in patients meeting severity criteria.', 4),
('d7000000-0000-0000-0000-000000000017', 'E', 'Adjunctive oral or intravenous corticosteroids (e.g. prednisolone), started as early as possible alongside anti-pneumocystis therapy', true, 'Correct. Adjunctive corticosteroids are indicated in moderate-to-severe PCP, defined by significant hypoxaemia (commonly PaO2 <9.3 kPa on room air or an alveolar-arterial gradient >35 mmHg), as they reduce the risk of respiratory deterioration and mortality associated with the inflammatory response to Pneumocystis organism death during treatment. They should be started early, ideally within 72 hours of starting anti-pneumocystis therapy, and tapered over around 3 weeks.', 5),
('d7000000-0000-0000-0000-000000000018', 'A', 'Initiate or optimise antiretroviral therapy promptly, as immune reconstitution is the only intervention shown to improve outcomes; there is no specific antiviral treatment for JC virus', true, 'Correct. Progressive multifocal leukoencephalopathy (PML), caused by reactivation of JC virus in the setting of severe immunosuppression, has no specific antiviral treatment. The only intervention shown to improve survival and outcomes is restoration of immune function, making prompt initiation or optimisation of antiretroviral therapy the cornerstone of management, even though this carries a risk of PML-IRIS (paradoxical worsening as immune function recovers), which itself may require corticosteroids if severe.', 1),
('d7000000-0000-0000-0000-000000000018', 'B', 'Start high-dose intravenous aciclovir as specific antiviral therapy for JC virus', false, 'Ruled out because aciclovir has no activity against JC virus (a polyomavirus, biologically distinct from herpesviruses) and has no role in PML treatment.', 2),
('d7000000-0000-0000-0000-000000000018', 'C', 'Start cidofovir as first-line specific antiviral therapy for PML', false, 'Ruled out because although cidofovir has been trialled for PML, it has not shown convincing clinical benefit and is not recommended as standard therapy; immune reconstitution via ART remains the primary evidence-based intervention.', 3),
('d7000000-0000-0000-0000-000000000018', 'D', 'Withhold antiretroviral therapy to avoid precipitating immune reconstitution inflammatory syndrome', false, 'Ruled out because withholding ART would remove the only intervention with proven benefit in PML; the correct approach is to start/optimise ART while monitoring closely for and managing IRIS if it occurs, not avoiding ART altogether.', 4),
('d7000000-0000-0000-0000-000000000018', 'E', 'Arrange whole-brain radiotherapy as the primary treatment modality', false, 'Ruled out because radiotherapy has no established role in the treatment of PML, which is an infective (not neoplastic) demyelinating process caused by JC virus.', 5),
('d7000000-0000-0000-0000-000000000019', 'A', 'Macrolide monotherapy alone, since Mycobacterium avium complex is highly susceptible to clarithromycin', false, 'Ruled out because macrolide monotherapy risks the rapid emergence of macrolide resistance in MAC; combination therapy is required to reduce this risk and achieve adequate treatment efficacy.', 1),
('d7000000-0000-0000-0000-000000000019', 'B', 'Standard four-drug anti-tuberculous therapy (rifampicin, isoniazid, pyrazinamide, ethambutol) as used for Mycobacterium tuberculosis', false, 'Ruled out because MAC is a distinct non-tuberculous mycobacterium with different antimicrobial susceptibility; standard first-line TB regimens (particularly isoniazid and pyrazinamide) are not appropriate or effective for MAC, which requires macrolide-based combination therapy instead.', 2),
('d7000000-0000-0000-0000-000000000019', 'C', 'Combination therapy with a macrolide (clarithromycin or azithromycin) plus ethambutol, with a third agent considered in severe disease, alongside prompt initiation of antiretroviral therapy', true, 'Correct. Disseminated MAC infection in advanced HIV is treated with combination antimycobacterial therapy, typically a macrolide (clarithromycin or azithromycin) plus ethambutol, with addition of a third agent (e.g. rifabutin, or a fluoroquinolone) considered in more severe disease or high mycobacterial burden. Antiretroviral therapy should also be initiated promptly, as immune reconstitution is central to long-term control, generally within about 2 weeks, with awareness of the risk of MAC-associated IRIS.', 3),
('d7000000-0000-0000-0000-000000000019', 'D', 'No specific antimycobacterial treatment is needed if antiretroviral therapy is started promptly, as immune reconstitution alone will clear disseminated MAC', false, 'Ruled out because disseminated MAC requires specific combination antimycobacterial therapy in addition to ART; relying on immune reconstitution alone without treating the active infection risks ongoing dissemination and clinical deterioration, and can also increase the risk of severe MAC-IRIS.', 4),
('d7000000-0000-0000-0000-000000000019', 'E', 'Primary MAC prophylaxis with azithromycin should be started instead of treatment, since the CD4 count is below the prophylaxis threshold', false, 'Ruled out because this patient has confirmed active disseminated disease (positive blood cultures with systemic symptoms), requiring full treatment-dose combination therapy, not prophylactic dosing, which is used to prevent MAC disease in asymptomatic patients with very low CD4 counts.', 5),
('d7000000-0000-0000-0000-000000000020', 'A', $x$Await confirmation of the source patient's current HIV viral load before deciding whether to start PEP$x$, false, 'Ruled out because PEP efficacy is highly time-dependent and should not be delayed while awaiting source patient results, particularly when the last known viral load is not recent enough to confidently assume ongoing suppression; PEP should be started promptly and can be discontinued later if risk assessment changes.', 1),
('d7000000-0000-0000-0000-000000000020', 'B', 'No action is required, as the source patient is on antiretroviral treatment and therefore poses no transmission risk', false, 'Ruled out because a viral load from eight months ago does not confirm current virological suppression, and even in patients with historically undetectable loads, adherence or other factors could have changed; a significant sharps injury with visible bleeding warrants PEP rather than assuming no risk.', 2),
('d7000000-0000-0000-0000-000000000020', 'C', 'Delay treatment until 96 hours post-exposure to allow full risk assessment and counselling to be completed', false, 'Ruled out because PEP has significantly reduced efficacy beyond 72 hours and is not generally recommended after this window; prompt action within the recommended timeframe is essential, with counselling and full assessment continuing alongside (not before) starting treatment.', 3),
('d7000000-0000-0000-0000-000000000020', 'D', 'Start post-exposure prophylaxis (a three-drug antiretroviral regimen) as soon as possible, ideally within an hour and no later than 72 hours after exposure, alongside baseline testing and follow-up', true, 'Correct. This represents a significant percutaneous exposure (hollow-bore needle, visible bleeding) to a source with HIV infection whose current virological control cannot be confirmed as fully suppressed (last viral load result is 8 months old). Post-exposure prophylaxis (PEP), typically a three-drug antiretroviral regimen, should be started as soon as possible after exposure, ideally within an hour and certainly within 72 hours, as efficacy diminishes with delay; baseline bloods (including HIV, hepatitis B/C serology) and follow-up testing should also be arranged, and PEP can be stopped later if the source is subsequently confirmed to pose negligible risk.', 4),
('d7000000-0000-0000-0000-000000000020', 'E', 'Administer a single-dose antiretroviral agent only, rather than a full multi-drug regimen', false, 'Ruled out because current HIV PEP guidance recommends a full three-drug antiretroviral regimen for the recommended duration (typically 28 days), not a single dose or agent, to maximise efficacy in preventing seroconversion.', 5),
('d7000000-0000-0000-0000-000000000021', 'A', 'Reassess ongoing need for the catheter and, if it must remain, consider changing it before starting targeted antibiotic therapy', true, 'Correct. In catheter-associated UTI, the indwelling catheter itself is a biofilm-associated nidus for infection, so management should include reassessing the ongoing need for catheterisation and, if catheterisation must continue, replacing the catheter around the time antibiotics are started, as this improves clinical response and reduces the biofilm bacterial burden compared with leaving the same catheter in place, in addition to sending culture-directed antimicrobial therapy.', 1),
('d7000000-0000-0000-0000-000000000021', 'B', 'Start empirical broad-spectrum antibiotics immediately without addressing the catheter itself', false, 'Ruled out because antibiotics alone, without addressing the catheter (removal if no longer needed, or replacement if still required), are less effective due to the persistent biofilm nidus of infection on the catheter surface, and does not represent complete management of CAUTI.', 2),
('d7000000-0000-0000-0000-000000000021', 'C', 'No treatment is required since asymptomatic bacteriuria in catheterised patients does not need antibiotics', false, 'Ruled out because this patient has new fever and confusion (systemic features suggestive of infection), not simple asymptomatic bacteriuria; asymptomatic bacteriuria in catheterised patients should not be treated, but a symptomatic catheter-associated UTI requires treatment.', 3),
('d7000000-0000-0000-0000-000000000021', 'D', 'Remove the catheter permanently regardless of ongoing clinical need for bladder drainage', false, 'Ruled out because catheter management should be individualised; if the catheter remains clinically necessary (e.g. for ongoing urinary retention or immobility post-surgery), the appropriate action is to reassess need and replace it rather than remove it outright, ensuring alternative bladder management is considered only if genuinely no longer needed.', 4),
('d7000000-0000-0000-0000-000000000021', 'E', 'Perform a bladder washout with antiseptic solution as the primary intervention', false, 'Ruled out because antiseptic bladder irrigation/washout is not recommended for prevention or treatment of catheter-associated UTI and is not supported by evidence as an effective intervention.', 5),
('d7000000-0000-0000-0000-000000000022', 'A', 'Remove the catheter immediately in all cases of catheter-related bloodstream infection regardless of organism or clinical stability', false, 'Ruled out because while removal is mandatory for certain high-risk organisms (e.g. Staphylococcus aureus, Candida species, or in cases of severe sepsis, tunnel infection, or persistent bacteraemia despite therapy), catheter salvage can reasonably be attempted first for lower-risk organisms like coagulase-negative staphylococci in a stable patient with a valuable, difficult-to-replace line.', 1),
('d7000000-0000-0000-0000-000000000022', 'B', 'Attempt catheter salvage with systemic antibiotics plus antibiotic lock therapy, given the difficulty of venous access and relatively low-virulence organism, with close monitoring for treatment failure', true, 'Correct. For catheter-related bloodstream infection with coagulase-negative staphylococci (a relatively low-virulence organism) in a clinically stable patient where the catheter is valuable and difficult to replace (as in long-term parenteral nutrition dependence), catheter salvage using systemic antibiotics combined with antibiotic lock therapy is a reasonable first strategy, with removal reserved for treatment failure, ongoing bacteraemia, clinical deterioration, or evidence of tunnel infection/complications.', 2),
('d7000000-0000-0000-0000-000000000022', 'C', 'Treat with oral antibiotics only, without any catheter-directed intervention or systemic intravenous therapy', false, 'Ruled out because catheter-related bloodstream infection requires systemic (typically intravenous) antimicrobial therapy directed at the causative organism, and catheter-specific strategies (removal or salvage with lock therapy) should be actively considered, not oral therapy alone with no catheter intervention.', 3),
('d7000000-0000-0000-0000-000000000022', 'D', 'Disregard the differential time to positivity result, as it has no diagnostic value in this context', false, 'Ruled out because differential time to positivity (catheter sample turning positive significantly earlier than a simultaneously drawn peripheral sample) is a validated method to help diagnose catheter-related bloodstream infection without removing the line, and is clinically useful information supporting the diagnosis here.', 4),
('d7000000-0000-0000-0000-000000000022', 'E', 'Perform a full catheter exchange over a guidewire rather than removal or salvage with lock therapy', false, 'Ruled out because guidewire exchange is generally avoided in the setting of documented catheter-related bloodstream infection, since it risks reintroducing infection onto the new catheter along the same tract; the preferred approaches are either salvage with systemic antibiotics plus lock therapy (low-risk organisms, stable patient) or full removal with insertion at a new site (high-risk organisms or complications).', 5),
('d7000000-0000-0000-0000-000000000023', 'A', 'Broad-spectrum intravenous antibiotics alone, with surgery reserved only if there is no improvement within 24-48 hours', false, 'Ruled out because antibiotics alone are inadequate for necrotising fasciitis; source control via urgent surgical debridement is essential and should not be delayed pending a trial of antibiotics, given the rapid progression and high mortality of this condition.', 1),
('d7000000-0000-0000-0000-000000000023', 'B', 'Obtain a contrast-enhanced CT scan first to confirm the diagnosis before involving the surgical team', false, 'Ruled out because when clinical suspicion for necrotising fasciitis is high (as here, with crepitus, rapid progression and gas in soft tissues already noted), surgical exploration/debridement should not be delayed for further imaging, which risks worsening outcomes; imaging may be useful in less clear-cut presentations but should not delay definitive surgical management here.', 2),
('d7000000-0000-0000-0000-000000000023', 'C', 'Manage as a simple superficial surgical site infection with wound dressing changes and oral antibiotics', false, 'Ruled out because the clinical picture (rapid progression, crepitus, systemic sepsis, gas in soft tissues) is characteristic of necrotising fasciitis, a life-threatening deep soft tissue infection requiring emergency surgical management, not simple wound care.', 3),
('d7000000-0000-0000-0000-000000000023', 'D', 'Administer intravenous immunoglobulin as the primary initial intervention before surgical assessment', false, 'Ruled out because although IVIG has been used as an adjunct in some cases of streptococcal toxic shock/necrotising fasciitis, it is not a substitute for urgent surgical debridement, which remains the primary, life-saving intervention and should not be delayed for other adjunctive therapies.', 4),
('d7000000-0000-0000-0000-000000000023', 'E', 'Urgent surgical debridement alongside broad-spectrum antibiotics and haemodynamic resuscitation, without delaying surgery for further imaging', true, 'Correct. Necrotising fasciitis is a surgical emergency; the priority is urgent, aggressive surgical debridement of all necrotic tissue, performed in parallel with broad-spectrum antibiotics (typically including agents active against streptococci, staphylococci, Gram-negatives and anaerobes, sometimes with clindamycin added for antitoxin effect) and aggressive resuscitation for septic shock. Surgery should not be delayed for extensive imaging when the diagnosis is already clinically strongly suspected, as delay is strongly associated with increased mortality.', 5),
('d7000000-0000-0000-0000-000000000024', 'A', 'Continue the same broad-spectrum empirical regimen unchanged for the full duration of treatment, since it is working clinically', false, 'Ruled out because continuing unnecessarily broad-spectrum therapy once a susceptible, narrower-spectrum-treatable organism is identified is poor antimicrobial stewardship practice, increasing the risk of resistance selection, Clostridioides difficile infection, and other broad-spectrum-associated harms without added clinical benefit.', 1),
('d7000000-0000-0000-0000-000000000024', 'B', 'Escalate to a broader carbapenem-based regimen to ensure complete organism coverage', false, 'Ruled out because escalation is not indicated when the causative organism has been identified and is susceptible to a narrower agent, and the patient is already improving clinically; broadening therapy in this context would be inappropriate and against stewardship principles.', 2),
('d7000000-0000-0000-0000-000000000024', 'C', 'Stop antibiotics immediately since a bacterial cause has now been confirmed and the patient is improving', false, 'Ruled out because identifying the causative organism confirms bacterial infection requiring an appropriate completed course of targeted therapy (de-escalated but not stopped), not immediate cessation, which would risk relapse or incomplete treatment.', 3),
('d7000000-0000-0000-0000-000000000024', 'D', 'De-escalate to a narrower-spectrum agent (e.g. flucloxacillin) targeted to the confirmed organism and its susceptibility, while continuing to monitor clinical response', true, 'Correct. Once culture and susceptibility results identify a single causative organism with a predictable susceptibility pattern, and the patient is clinically improving, antimicrobial therapy should be de-escalated from broad-spectrum empirical cover to a narrower, pathogen-directed agent. This reduces selection pressure for resistance, minimises toxicity and cost, and is a core principle of antimicrobial stewardship in VAP management, alongside determining an appropriate total treatment duration.', 4),
('d7000000-0000-0000-0000-000000000024', 'E', 'Add an aminoglycoside to the current regimen to broaden Gram-negative cover despite no Gram-negative organism being isolated', false, 'Ruled out because adding empirical Gram-negative cover is unnecessary once cultures have specifically identified a single susceptible Gram-positive organism and no evidence supports additional coverage; this would represent unwarranted antibiotic broadening.', 5),
('d7000000-0000-0000-0000-000000000025', 'A', 'Alcohol-based hand gel is sufficient for hand hygiene, as it is highly effective against all healthcare-associated pathogens including C. difficile', false, 'Ruled out because alcohol-based hand gels do not reliably kill C. difficile spores; this is a specific and important exception to standard alcohol-gel-based hand hygiene practice, requiring soap and water instead for effective spore removal.', 1),
('d7000000-0000-0000-0000-000000000025', 'B', 'Standard (non-sporicidal) detergent-based cleaning products are equally effective as chlorine-based agents against C. difficile spores', false, 'Ruled out because standard detergent-based cleaning agents do not reliably inactivate C. difficile spores; sporicidal agents (typically chlorine-based/hypochlorite solutions) are specifically required for adequate environmental decontamination during an outbreak.', 2),
('d7000000-0000-0000-0000-000000000025', 'C', 'Use soap and water hand hygiene (rather than alcohol-based hand gel alone) plus chlorine-based (sporicidal) environmental cleaning agents', true, 'Correct. C. difficile forms spores that are resistant to alcohol-based hand sanitisers and many standard cleaning agents; effective control specifically requires mechanical removal of spores via soap-and-water handwashing (alcohol gel is ineffective against spores) and use of sporicidal agents such as chlorine-based (hypochlorite) solutions for environmental decontamination, in addition to antimicrobial stewardship to reduce high-risk antibiotic use and contact precautions/isolation of affected patients.', 3),
('d7000000-0000-0000-0000-000000000025', 'D', 'Isolation precautions are unnecessary for C. difficile as it is not transmissible between patients on a ward', false, 'Ruled out because C. difficile is readily transmissible via the faecal-oral route and environmental contamination with spores; contact precautions and, where possible, single-room isolation of affected patients are important components of outbreak control, not something to omit.', 4),
('d7000000-0000-0000-0000-000000000025', 'E', 'Restricting visitors is the single most effective measure and hand hygiene technique is of secondary importance', false, 'Ruled out because while visitor restriction may have some role during outbreaks, hand hygiene technique (specifically soap and water for spore removal) and environmental sporicidal cleaning are the most directly evidence-based and specific measures for controlling C. difficile transmission on a ward.', 5),
('d7000000-0000-0000-0000-000000000026', 'A', 'No specific precautions are required until a positive screening result is confirmed', false, 'Ruled out because waiting for a positive result before implementing precautions risks unrecognised transmission during the intervening period; pre-emptive isolation based on recognised risk factors (recent overseas hospitalisation) is standard practice while results are pending.', 1),
('d7000000-0000-0000-0000-000000000026', 'B', 'Screen only for MRSA, as CRE screening is not indicated based on overseas hospital admission alone', false, 'Ruled out because recent admission to a healthcare facility abroad (particularly with an extended stay) is a well-recognised risk factor specifically warranting CRE (and other multidrug-resistant Gram-negative organism) screening, in addition to standard MRSA screening, not instead of it.', 2),
('d7000000-0000-0000-0000-000000000026', 'C', 'Administer prophylactic carbapenem antibiotics until screening results are available', false, 'Ruled out because prophylactic antibiotics are not indicated for CRE screening purposes and would be inappropriate antimicrobial use; the correct approach is isolation/contact precautions and targeted screening, not empirical antibiotic prophylaxis.', 3),
('d7000000-0000-0000-0000-000000000026', 'D', 'Screening and isolation precautions can be deferred until the patient develops clinical signs of infection', false, 'Ruled out because the purpose of admission screening and pre-emptive isolation is to detect and control asymptomatic colonisation before clinical infection or transmission occurs; deferring until symptomatic infection develops defeats the purpose of proactive infection control screening.', 4),
('d7000000-0000-0000-0000-000000000026', 'E', 'Place the patient in a single room (or cohort with other screened/isolated high-risk patients) on contact precautions until screening results are confirmed negative', true, 'Correct. Patients with recent overseas healthcare contact, particularly prolonged admission in regions/settings with higher prevalence of multidrug-resistant organisms, are at increased risk of carbapenem-resistant Enterobacteriaceae (CRE) carriage. Pending screening results, pre-emptive isolation (single room) with contact precautions (gloves, gowns, dedicated equipment, meticulous hand hygiene) is recommended to prevent potential transmission, given the significant clinical and infection control consequences of CRE spread within a healthcare facility.', 5),
('d7000000-0000-0000-0000-000000000027', 'A', 'Undertake a decolonisation regimen (e.g. nasal mupirocin and chlorhexidine body washes) prior to surgery, and ensure appropriate peri-operative antibiotic prophylaxis covers MRSA', true, 'Correct. Pre-operative MRSA decolonisation using topical nasal mupirocin and antiseptic (e.g. chlorhexidine) body washing reduces the risk of surgical site infection, including prosthetic joint infection, in known MRSA carriers undergoing elective orthopaedic surgery such as joint replacement. Peri-operative antibiotic prophylaxis should also be adjusted to ensure adequate anti-MRSA cover (e.g. incorporating a glycopeptide such as vancomycin/teicoplanin) rather than relying on standard prophylaxis alone.', 1),
('d7000000-0000-0000-0000-000000000027', 'B', 'Cancel the surgery indefinitely until MRSA carriage is eradicated and confirmed negative on repeat swabs', false, 'Ruled out because elective surgery does not need to be cancelled or delayed indefinitely for MRSA colonisation; decolonisation therapy prior to surgery, combined with appropriate prophylaxis, is the standard approach rather than requiring confirmed eradication before proceeding.', 2),
('d7000000-0000-0000-0000-000000000027', 'C', 'Proceed with standard surgical antibiotic prophylaxis with no decolonisation or adjustment, as MRSA colonisation does not increase surgical site infection risk', false, 'Ruled out because MRSA colonisation is a recognised risk factor for MRSA-related surgical site infection, including serious prosthetic joint infection; both pre-operative decolonisation and adjusted antibiotic prophylaxis are recommended to mitigate this risk, rather than proceeding unchanged.', 3),
('d7000000-0000-0000-0000-000000000027', 'D', 'Treat with a full systemic course of oral antibiotics for two weeks before surgery to eradicate MRSA carriage', false, 'Ruled out because systemic antibiotic courses are not the standard approach to MRSA decolonisation; topical nasal and skin decolonisation regimens are used instead, reserving systemic antibiotics for active infection rather than asymptomatic colonisation.', 4),
('d7000000-0000-0000-0000-000000000027', 'E', 'No specific action is required, as MRSA nasal colonisation is a normal, clinically insignificant finding requiring no intervention', false, 'Ruled out because MRSA nasal colonisation is clinically significant in the context of upcoming surgery, particularly prosthetic joint implantation, given the substantially increased morbidity of MRSA-related prosthetic infection; pre-operative decolonisation and adjusted prophylaxis are recommended, not inaction.', 5),
('d7000000-0000-0000-0000-000000000028', 'A', 'Single-stage revision arthroplasty (removal and immediate re-implantation of a new prosthesis) as the preferred approach', false, 'Ruled out because single-stage revision is generally reserved for situations where DAIR is not appropriate (e.g. longer-standing infection, sinus tract, prosthesis loosening) but eradication in one operation is still felt achievable; for an acute infection with a well-fixed implant and short symptom duration, DAIR is preferred as a less invasive first-line strategy.', 1),
('d7000000-0000-0000-0000-000000000028', 'B', 'Two-stage revision arthroplasty (removal of prosthesis, antibiotic spacer, delayed re-implantation) as the only appropriate option', false, 'Ruled out because two-stage revision is typically reserved for chronic prosthetic joint infection, infections with difficult-to-treat organisms, loosening/sinus tract formation, or DAIR failure, rather than being the only option for an acute, well-fixed infection amenable to a joint-preserving approach.', 2),
('d7000000-0000-0000-0000-000000000028', 'C', 'Long-term suppressive oral antibiotics alone without any surgical intervention', false, 'Ruled out because surgical source control (debridement, at minimum) is required for prosthetic joint infection; antibiotics alone without surgical intervention are inadequate to control biofilm-associated infection on a retained prosthesis, though long-term suppressive antibiotics may have a role in specific circumstances where surgery is not feasible, not as first-line management here.', 3),
('d7000000-0000-0000-0000-000000000028', 'D', 'Debridement, antibiotics and implant retention (DAIR), with a well-fixed prosthesis and short symptom duration since implantation', true, 'Correct. DAIR is the preferred surgical strategy for acute prosthetic joint infection (typically within about 3-4 weeks of implantation, or acute haematogenous infection with short symptom duration) when the prosthesis is well-fixed and there is no sinus tract, combined with prolonged targeted antibiotic therapy (often including rifampicin combination therapy for staphylococcal biofilm infection once source control is achieved). This avoids the greater morbidity of prosthesis removal while achieving good outcomes in appropriately selected acute cases.', 4),
('d7000000-0000-0000-0000-000000000028', 'E', 'Amputation of the affected limb as the definitive management for this presentation', false, 'Ruled out because amputation is reserved for severe, limb- or life-threatening infection unresponsive to more conservative surgical strategies, not as an appropriate first approach to an acute, well-fixed prosthetic joint infection amenable to DAIR.', 5),
('d7000000-0000-0000-0000-000000000029', 'A', 'Continue routine ward operations, including new admissions, as norovirus is generally a self-limiting illness in healthy adults', false, 'Ruled out because although norovirus illness is usually self-limiting in healthy individuals, on a healthcare ward (particularly one with elderly or vulnerable patients) it can cause rapid, extensive outbreaks with significant morbidity and disruption to care; ward closure to new admissions is a standard, evidence-based outbreak control measure.', 1),
('d7000000-0000-0000-0000-000000000029', 'B', 'Close the ward to new admissions and transfers, cohort or isolate symptomatic patients, and reinforce hand hygiene (soap and water) and enhanced environmental cleaning', true, $x$Correct. Norovirus is highly contagious via the faecal-oral and aerosolised vomitus routes, and outbreaks on healthcare wards are managed by promptly closing the affected ward to new admissions/transfers (to limit spread to susceptible patients), isolating or cohorting symptomatic patients, reinforcing soap-and-water hand hygiene (alcohol gel has reduced efficacy against norovirus), and enhanced cleaning of the environment, given the virus's low infectious dose and environmental persistence.$x$, 2),
('d7000000-0000-0000-0000-000000000029', 'C', 'Rely on alcohol-based hand gel alone for hand hygiene, as it is highly effective against norovirus', false, 'Ruled out because alcohol-based hand gels have reduced efficacy against non-enveloped viruses such as norovirus compared with soap and water, which provides better mechanical removal; soap and water hand hygiene should be emphasised during norovirus outbreaks.', 3),
('d7000000-0000-0000-0000-000000000029', 'D', 'Treat all symptomatic patients empirically with broad-spectrum antibiotics to prevent secondary bacterial infection', false, 'Ruled out because norovirus is a viral infection for which antibiotics have no role in treatment; management is supportive (rehydration) alongside infection control measures to limit spread, not antimicrobial therapy.', 4),
('d7000000-0000-0000-0000-000000000029', 'E', 'Discharge all affected patients home immediately to clear the ward of infection', false, 'Ruled out because discharging unwell, potentially still-infectious patients is not an appropriate outbreak control measure and could spread infection into the community or care settings; the priority is containment via isolation/cohorting and ward closure to new admissions, with discharge decisions made on individual clinical grounds.', 5),
('d7000000-0000-0000-0000-000000000030', 'A', 'No action is required, as prior completion of a full hepatitis B vaccination course five years ago guarantees ongoing immunity', false, 'Ruled out because vaccine-induced immunity can wane over time and some individuals are non-responders or lose protective antibody levels; without a confirmed adequate anti-HBs level, immunity cannot be assumed, particularly given the high infectivity of this specific source.', 1),
('d7000000-0000-0000-0000-000000000030', 'B', 'Give hepatitis B immunoglobulin only, without any vaccine booster, since the healthcare worker was previously vaccinated', false, 'Ruled out because immunoglobulin alone provides only short-term passive protection; a vaccine booster (or full revaccination if a non-responder) is also needed to ensure more durable protection, especially when the prior antibody response is unconfirmed.', 2),
('d7000000-0000-0000-0000-000000000030', 'C', $x$Urgently check the healthcare worker's anti-HBs antibody level; if inadequate or unknown response cannot be confirmed rapidly, give hepatitis B immunoglobulin plus an accelerated vaccine booster given the high-risk source$x$, true, $x$Correct. Following significant percutaneous exposure to a highly infectious hepatitis B source (HBeAg positive, high viral load), management depends on the exposed person's immune status. A previously vaccinated individual with unknown or unconfirmed anti-HBs response should have this checked urgently; if a protective response cannot be rapidly confirmed, hepatitis B immunoglobulin (providing immediate passive protection) should be given alongside an accelerated vaccine booster, given the high transmissibility of the source in this scenario. This differs from a known, confirmed responder, who would only need a booster dose without immunoglobulin.$x$, 3),
('d7000000-0000-0000-0000-000000000030', 'D', 'Start hepatitis B antiviral therapy (e.g. tenofovir) as post-exposure prophylaxis, as used for HIV exposure', false, 'Ruled out because routine post-exposure management for hepatitis B relies on immunoglobulin and vaccination according to immune status, not antiviral drug prophylaxis, which is not standard practice for hepatitis B occupational exposure in this context.', 4),
('d7000000-0000-0000-0000-000000000030', 'E', 'Defer any action until hepatitis B surface antigen testing of the healthcare worker at 6 months confirms whether transmission has occurred', false, 'Ruled out because post-exposure prophylaxis must be given promptly after exposure to be effective in preventing infection; waiting until 6 months to check for established infection would forgo the window in which preventive treatment is effective.', 5),
('d7000000-0000-0000-0000-000000000031', 'A', 'Continue further large-volume crystalloid boluses alone without introducing a vasopressor', false, 'Ruled out because persistent hypotension and rising lactate despite initial adequate fluid resuscitation indicates ongoing shock requiring vasopressor support; continued unguided large-volume fluid administration risks fluid overload without addressing the underlying vasoplegia, and delays appropriate escalation of care.', 1),
('d7000000-0000-0000-0000-000000000031', 'B', 'Start intravenous dopamine as the first-line vasopressor in preference to noradrenaline', false, 'Ruled out because dopamine is no longer recommended as a first-line vasopressor in septic shock due to a higher risk of arrhythmias and, in some trials, increased mortality compared with noradrenaline, which is preferred as first-line therapy.', 2),
('d7000000-0000-0000-0000-000000000031', 'C', 'Delay any vasopressor therapy until source control has been achieved with interventional radiology drainage', false, 'Ruled out because vasopressor support should not be delayed pending source control; haemodynamic stabilisation and source control should proceed in parallel as both are time-critical in septic shock, not sequentially with vasopressors withheld.', 3),
('d7000000-0000-0000-0000-000000000031', 'D', 'Start high-dose intravenous hydrocortisone as the primary intervention in preference to vasopressor therapy', false, 'Ruled out because corticosteroids are considered as an adjunct in septic shock that remains refractory to fluids and vasopressors (i.e. vasopressor-dependent shock), not as a substitute for, or preceding, first-line vasopressor therapy itself.', 4),
('d7000000-0000-0000-0000-000000000031', 'E', 'Start intravenous noradrenaline as the first-line vasopressor to target a mean arterial pressure of at least 65 mmHg, while continuing appropriate fluid resuscitation and pursuing urgent source control', true, 'Correct. In septic shock persisting despite adequate initial fluid resuscitation, noradrenaline is the first-line vasopressor of choice, titrated to achieve a mean arterial pressure target of at least 65 mmHg, as per Surviving Sepsis Campaign guidance. Ongoing fluid administration should be judicious and guided by dynamic markers of fluid responsiveness rather than further large fixed-volume boluses, and definitive source control (here, drainage of the abscess) remains a critical, time-sensitive priority alongside haemodynamic support.', 5),
('d7000000-0000-0000-0000-000000000032', 'A', 'Arrange echocardiography (transthoracic, with transoesophageal if risk factors or inconclusive findings) to assess for infective endocarditis, as this influences the required duration and choice of therapy', true, $x$Correct. All patients with Staphylococcus aureus bacteraemia should be evaluated for infective endocarditis, given the organism's high propensity for endovascular seeding, as this significantly influences antibiotic duration (typically prolonged, e.g. around 4-6 weeks for complicated bacteraemia/endocarditis versus a shorter course for genuinely uncomplicated bacteraemia) and management. Echocardiography (starting with transthoracic, escalating to transoesophageal if initial imaging is inconclusive or risk factors for endocarditis are present) is a key part of this assessment, alongside clinical evaluation, repeat blood cultures to confirm clearance, and assessment for metastatic foci of infection.$x$, 1),
('d7000000-0000-0000-0000-000000000032', 'B', 'No further investigation is required, as clearance of blood cultures at 48 hours confirms uncomplicated bacteraemia', false, $x$Ruled out because clearance of bacteraemia alone does not exclude endocarditis or other deep-seated complications of Staphylococcus aureus bacteraemia; formal assessment (including echocardiography) is required in essentially all cases due to the organism's high virulence and propensity for endovascular infection.$x$, 2),
('d7000000-0000-0000-0000-000000000032', 'C', 'Treat with a fixed 7-day course of oral antibiotics regardless of further assessment findings', false, 'Ruled out because duration of therapy for Staphylococcus aureus bacteraemia should be individualised based on assessment for complications (endocarditis, metastatic foci, persistent bacteraemia), and a short fixed oral course is generally inadequate, particularly without first excluding endocarditis or other deep infection.', 3),
('d7000000-0000-0000-0000-000000000032', 'D', 'Perform a CT pulmonary angiogram as the key investigation to guide duration of therapy', false, 'Ruled out because while imaging for metastatic foci may sometimes be relevant depending on clinical findings, the key investigation specifically indicated in essentially all cases of Staphylococcus aureus bacteraemia to guide management is echocardiographic assessment for endocarditis, not CT pulmonary angiography as a routine step.', 4),
('d7000000-0000-0000-0000-000000000032', 'E', 'Switch immediately to oral antibiotics once cultures are negative, without further assessment for endocarditis', false, 'Ruled out because negative repeat cultures alone do not determine suitability for oral switch or overall duration; assessment for endocarditis and other complications is required first, as this significantly changes the recommended treatment approach and duration.', 5),
('d7000000-0000-0000-0000-000000000033', 'A', 'Continue antibiotic therapy alone and defer any consideration of surgery until a full six-week course is completed', false, 'Ruled out because heart failure secondary to valve destruction in endocarditis is a recognised indication for early (often urgent) surgery rather than delaying intervention until antibiotics are completed, given the risk of rapid haemodynamic deterioration.', 1),
('d7000000-0000-0000-0000-000000000033', 'B', 'Arrange elective outpatient valve surgery only if symptoms fail to improve over the next 3 months', false, 'Ruled out because this presentation represents an urgent, evolving complication (new heart failure from acute valve regurgitation) requiring prompt inpatient surgical referral, not deferred elective outpatient assessment.', 2),
('d7000000-0000-0000-0000-000000000033', 'C', 'Increase diuretic therapy alone and manage conservatively without surgical referral', false, 'Ruled out because although diuretics may provide symptomatic support, they do not address the underlying structural valve damage causing heart failure; definitive management requires surgical referral given this recognised indication for early surgery.', 3),
('d7000000-0000-0000-0000-000000000033', 'D', 'Urgent cardiac surgical referral for valve surgery, given new heart failure secondary to acute aortic regurgitation', true, 'Correct. Heart failure due to valve dysfunction (here, acute/worsening aortic regurgitation causing pulmonary oedema) is one of the strongest and most time-critical indications for early surgery in infective endocarditis, as continued medical therapy alone carries a high risk of further haemodynamic deterioration and mortality. Surgery should not be delayed for completion of a full antibiotic course when such indications are present.', 4),
('d7000000-0000-0000-0000-000000000033', 'E', 'Screen for colorectal malignancy as the immediate priority before addressing his cardiac status', false, 'Ruled out because although Streptococcus gallolyticus (bovis) bacteraemia/endocarditis is strongly associated with colorectal neoplasia and colonoscopy should be arranged as part of his overall management, this is not the immediate priority when he has developed acute, deteriorating heart failure from valve destruction requiring urgent surgical referral first.', 5),
('d7000000-0000-0000-0000-000000000034', 'A', 'Await blood culture and other microbiology results before starting any antibiotic therapy', false, 'Ruled out because delaying empirical antibiotics pending culture results in febrile neutropenia significantly increases the risk of progression to severe sepsis and death; antibiotics should be started empirically within one hour without waiting for results.', 1),
('d7000000-0000-0000-0000-000000000034', 'B', 'Manage as an outpatient with oral antibiotics given stable observations and neutropenic sepsis being unlikely with such reassuring vital signs', false, $x$Ruled out because reassuring initial observations do not reliably exclude significant risk in febrile neutropenia, and standard practice is prompt hospital-based assessment with intravenous empirical antibiotics; low-risk outpatient pathways exist in some settings but require specific validated risk stratification, not simply 'looking well' at a single time point, and are not the most appropriate first answer here.$x$, 2),
('d7000000-0000-0000-0000-000000000034', 'C', 'Start empirical broad-spectrum intravenous antibiotics (e.g. piperacillin-tazobactam or an institutional equivalent) within one hour of presentation, after taking blood cultures (including from the line)', true, 'Correct. Febrile neutropenia is a medical emergency regardless of how clinically well the patient initially appears, given the risk of rapid deterioration in the absence of a functioning immune response; empirical broad-spectrum antibiotics with adequate Gram-negative (including Pseudomonas) cover should be started within one hour of presentation, ideally after (but without delay for) obtaining blood cultures from both peripheral and central line sites.', 3),
('d7000000-0000-0000-0000-000000000034', 'D', 'Remove the central venous catheter immediately as the first management step before starting antibiotics', false, 'Ruled out because immediate line removal is not the automatic first step in febrile neutropenia without a specific line-related indication (e.g. tunnel infection, septic shock unresponsive to therapy, confirmed line-associated organism where salvage fails); the priority is prompt empirical antibiotics after appropriate cultures, with line management decisions made subsequently based on clinical course and culture results.', 4),
('d7000000-0000-0000-0000-000000000034', 'E', 'Start antifungal therapy alone, as fungal infection is the most likely cause of fever in this setting', false, 'Ruled out because bacterial infection is the most common and immediately concerning cause of fever in neutropenia, requiring prompt broad-spectrum antibacterial therapy first; antifungal therapy is generally added if fever persists despite adequate antibacterial treatment after a defined interval, not used as initial monotherapy.', 5),
('d7000000-0000-0000-0000-000000000035', 'A', 'Start empirical oral antibiotics and review in the outpatient clinic in one week', false, 'Ruled out because septic arthritis in a systemically unwell patient requires urgent inpatient assessment, aspiration and intravenous antibiotics, not oral outpatient management, given the risk of rapid joint destruction and systemic sepsis.', 1),
('d7000000-0000-0000-0000-000000000035', 'B', 'Urgent joint aspiration for synovial fluid microscopy, culture and crystal analysis, followed immediately by empirical intravenous antibiotics without waiting for culture results, alongside orthopaedic assessment for possible surgical washout', true, 'Correct. Septic arthritis is an orthopaedic and medical emergency requiring urgent joint aspiration (to confirm the diagnosis, guide antibiotic choice, and differentiate from crystal arthropathy) and prompt empirical intravenous antibiotic therapy started immediately after aspiration without waiting for culture results, given the risk of rapid, irreversible joint destruction. Orthopaedic involvement is essential, as surgical washout/debridement is often required in addition to antibiotics, particularly in a systemically unwell patient.', 2),
('d7000000-0000-0000-0000-000000000035', 'C', 'Delay antibiotics until joint aspiration culture results are available in 48-72 hours to avoid affecting culture yield', false, 'Ruled out because although aspiration should ideally precede antibiotics where feasible without significant delay, definitive antibiotic therapy should not be delayed for days awaiting culture results once aspiration has been performed, given the urgency of treating septic arthritis and the risk of joint destruction and systemic sepsis.', 3),
('d7000000-0000-0000-0000-000000000035', 'D', 'Manage with analgesia and immobilisation alone, treating this as an inflammatory (crystal) arthropathy without further investigation', false, 'Ruled out because although crystal arthropathy is an important differential, the presence of fever and systemic sepsis in this context mandates urgent investigation (aspiration) and empirical treatment for septic arthritis, as missing this diagnosis risks joint destruction and sepsis-related mortality.', 4),
('d7000000-0000-0000-0000-000000000035', 'E', 'Arrange elective MRI of the knee as the first investigation, with treatment deferred until imaging is complete', false, 'Ruled out because urgent joint aspiration (not elective MRI) is the key initial investigation in suspected septic arthritis, as it provides immediate diagnostic and microbiological information and treatment should not be delayed for elective imaging in a systemically unwell patient.', 5),
('d7000000-0000-0000-0000-000000000036', 'A', 'Toxic shock syndrome, likely due to a Staphylococcus aureus superantigen exotoxin (TSST-1); management includes source control (foreign body removal, already performed), aggressive supportive care, and antibiotics with anti-toxin activity such as clindamycin combined with an agent active against Staphylococcus aureus', true, 'Correct. This presentation (fever, diffuse erythroderma, hypotension, multi-organ involvement, associated with tampon use, and negative blood cultures) is classic for toxic shock syndrome, typically caused by toxin-producing Staphylococcus aureus (TSST-1) or, less commonly, group A Streptococcus. Blood cultures are often negative because the syndrome is toxin-mediated rather than a true bacteraemic process. Management requires source control (removal of the foreign body, as has been done), aggressive haemodynamic and organ support, and antibiotics including an agent such as clindamycin, which inhibits toxin production via protein synthesis inhibition, in addition to an antistaphylococcal agent.', 1),
('d7000000-0000-0000-0000-000000000036', 'B', 'Meningococcal septicaemia, requiring immediate benzylpenicillin and public health notification for contact prophylaxis', false, 'Ruled out because although meningococcal septicaemia can cause a rash and shock, the specific clinical context (tampon use, diffuse erythroderma rather than a purpuric rash, and negative blood cultures) is much more consistent with toxic shock syndrome than meningococcal disease.', 2),
('d7000000-0000-0000-0000-000000000036', 'C', 'Anaphylaxis to an unidentified allergen, requiring intramuscular adrenaline as the priority treatment', false, 'Ruled out because the clinical picture (fever, multi-organ dysfunction over days, association with tampon use) is not consistent with an acute IgE-mediated anaphylactic reaction, which typically has a much more rapid onset and different clinical features (e.g. angioedema, wheeze, urticaria) without the multi-system organ dysfunction pattern described.', 3),
('d7000000-0000-0000-0000-000000000036', 'D', 'Disseminated intravascular coagulation as a primary haematological disorder unrelated to infection, requiring fresh frozen plasma as first-line treatment', false, 'Ruled out because although DIC-like coagulopathy can occur as a complication of severe sepsis/toxic shock, it is not the primary diagnosis here; the underlying toxin-mediated infective process (toxic shock syndrome) must be identified and treated (source control, antibiotics with anti-toxin activity), with coagulopathy managed as part of supportive multi-organ care rather than treated in isolation.', 4),
('d7000000-0000-0000-0000-000000000036', 'E', 'A viral exanthem requiring only supportive management with no role for antibiotics', false, 'Ruled out because the clinical picture with hypotension, multi-organ dysfunction and a clear risk factor (retained tampon) strongly indicates a toxin-mediated bacterial process (toxic shock syndrome) requiring specific source control and antibiotic therapy with anti-toxin activity, not simple supportive care alone as for a benign viral exanthem.', 5),
('d7000000-0000-0000-0000-000000000037', 'A', 'Continue escalating the noradrenaline dose indefinitely without introducing an additional agent', false, 'Ruled out because very high-dose catecholamine monotherapy carries increasing risks of arrhythmia and peripheral ischaemia, and evidence supports adding a second agent (typically vasopressin) rather than escalating a single catecholamine indefinitely.', 1),
('d7000000-0000-0000-0000-000000000037', 'B', 'Switch from noradrenaline to dopamine monotherapy at this stage', false, 'Ruled out because dopamine is not recommended as a preferred alternative or replacement for noradrenaline in septic shock due to a higher risk of arrhythmias and less favourable outcome data; adding vasopressin as a second agent is preferred over switching to dopamine.', 2),
('d7000000-0000-0000-0000-000000000037', 'C', 'Add adrenaline as the preferred second-line vasopressor of choice', false, 'Ruled out because while adrenaline can be used as a second/third-line agent in refractory septic shock in some situations, vasopressin is generally the preferred first additional agent when noradrenaline alone is insufficient, according to major sepsis guidelines.', 3),
('d7000000-0000-0000-0000-000000000037', 'D', 'Add vasopressin as a second agent to help achieve target mean arterial pressure and potentially allow noradrenaline dose reduction', true, 'Correct. In septic shock inadequately controlled on moderate-to-high dose noradrenaline alone, adding a second vasopressor with a different mechanism of action, most commonly vasopressin, is recommended. This can help achieve the mean arterial pressure target, may allow some reduction in catecholamine dose (with potential benefit in reducing catecholamine-related adverse effects such as arrhythmias), rather than escalating noradrenaline indefinitely as monotherapy.', 4),
('d7000000-0000-0000-0000-000000000037', 'E', 'Give a further large fluid bolus rather than adding any additional vasopressor', false, 'Ruled out because in a patient already adequately fluid-resuscitated who remains hypotensive on vasopressor therapy, further large fluid boluses are unlikely to improve haemodynamics further and risk fluid overload; vasopressor escalation (adding a second agent) is the more appropriate next step.', 5),
('d7000000-0000-0000-0000-000000000038', 'A', 'Start fluconazole as first-line therapy given its favourable oral bioavailability', false, 'Ruled out because Candida glabrata commonly shows reduced fluconazole susceptibility, making it an unreliable first-line choice for this species, particularly in a critically ill patient; an echinocandin is preferred.', 1),
('d7000000-0000-0000-0000-000000000038', 'B', 'Start an echinocandin (e.g. micafungin or caspofungin), given reduced fluconazole susceptibility commonly seen with Candida glabrata and the severity of critical illness', true, 'Correct. Candida glabrata frequently exhibits reduced susceptibility or resistance to fluconazole, making an echinocandin the preferred first-line agent for candidaemia caused by this species, particularly in a critically ill patient. Prompt removal of the infected central venous catheter (source control) remains essential alongside systemic antifungal therapy, and susceptibility testing should guide any subsequent step-down therapy.', 2),
('d7000000-0000-0000-0000-000000000038', 'C', 'Retain the central venous catheter unchanged, as removal is not necessary once appropriate antifungal therapy is started', false, 'Ruled out because catheter removal (source control) is a critical component of managing catheter-associated candidaemia and significantly improves outcomes; retaining an infected line despite appropriate antifungal therapy risks persistent or relapsing infection.', 3),
('d7000000-0000-0000-0000-000000000038', 'D', 'Treat with oral nystatin as definitive systemic therapy for this bloodstream infection', false, 'Ruled out because nystatin is not absorbed systemically and has no role in treating invasive candidaemia; systemic antifungal therapy (e.g. an echinocandin) is required for bloodstream infection.', 4),
('d7000000-0000-0000-0000-000000000038', 'E', 'Withhold antifungal therapy until species-level identification and full susceptibility testing are complete', false, 'Ruled out because empirical antifungal therapy should be started promptly once candidaemia is identified (the organism here is already identified to species level as Candida glabrata, supporting empirical echinocandin choice), given the high mortality associated with delayed treatment; therapy should not be withheld pending further testing beyond what is already known.', 5),
('d7000000-0000-0000-0000-000000000039', 'A', 'Await blood culture results before starting any antibiotic therapy, given her stable underlying health otherwise', false, 'Ruled out because OPSI can progress to death within hours; empirical antibiotics must be given immediately once sepsis is suspected in an asplenic patient, without waiting for culture confirmation.', 1),
('d7000000-0000-0000-0000-000000000039', 'B', 'Reassure the patient that splenectomy carries no long-term infection risk once the acute surgical recovery period has passed', false, 'Ruled out because asplenia confers a lifelong increased risk of overwhelming sepsis with encapsulated organisms, not a risk limited to the immediate post-operative period; this is precisely why asplenic patients require ongoing vaccination, prophylaxis considerations and heightened clinical vigilance.', 2),
('d7000000-0000-0000-0000-000000000039', 'C', 'Arrange outpatient review in 24-48 hours, as her symptoms are most likely a self-limiting viral illness', false, 'Ruled out because her presentation (fever, rigors, confusion, developing purpuric rash) in the context of asplenia is highly concerning for overwhelming post-splenectomy sepsis, a medical emergency requiring immediate hospital-based treatment, not outpatient deferral.', 3),
('d7000000-0000-0000-0000-000000000039', 'D', 'Perform a full splenic function assessment (e.g. Howell-Jolly body count) before deciding on antibiotic therapy', false, 'Ruled out because her splenectomy history is already known and confirmed surgically; further splenic function testing is irrelevant to the immediate emergency management of suspected overwhelming sepsis, which requires immediate empirical antibiotics without diagnostic delay.', 4),
('d7000000-0000-0000-0000-000000000039', 'E', 'Administer immediate empirical broad-spectrum intravenous antibiotics without delay, recognising overwhelming post-splenectomy infection (OPSI) as a life-threatening emergency typically caused by encapsulated organisms such as Streptococcus pneumoniae', true, $x$Correct. Patients who are asplenic or hyposplenic are at markedly increased risk of overwhelming, rapidly progressive sepsis (OPSI), most commonly caused by encapsulated organisms (particularly Streptococcus pneumoniae, also Haemophilus influenzae type b and Neisseria meningitidis), due to loss of the spleen's role in clearing encapsulated bacteria and opsonised organisms. This is a medical emergency with very high mortality if treatment is delayed, requiring immediate empirical broad-spectrum antibiotics (before any further investigation) as the top priority, alongside full septic shock resuscitation.$x$, 5),
('d7000000-0000-0000-0000-000000000040', 'A', 'A minimum of 14 days of intravenous therapy is mandatory for all Gram-negative bacteraemia regardless of clinical response', false, 'Ruled out because trial evidence now supports shorter durations (around 7 days) for uncomplicated Gram-negative bacteraemia with good clinical response and source control, making a mandatory 14-day intravenous course unnecessarily prolonged in this scenario.', 1),
('d7000000-0000-0000-0000-000000000040', 'B', 'A single dose of antibiotics is sufficient once blood cultures have cleared', false, 'Ruled out because a full, though shortened, course of antibiotics (around 7 days in this uncomplicated scenario) is still required to ensure eradication of infection; a single dose is inadequate despite negative repeat cultures.', 2),
('d7000000-0000-0000-0000-000000000040', 'C', 'A shorter total course, typically around 7 days, is appropriate given rapid clinical response, source control, and uncomplicated Gram-negative bacteraemia from a urinary source', true, 'Correct. Evidence from randomised trials supports shorter total treatment durations (commonly around 7 days) for uncomplicated Gram-negative bacteraemia, including from a urinary source, in patients who respond rapidly to appropriate therapy, without complicating features (undrained collection, obstruction, immunosuppression, endovascular infection, or prosthetic material). Longer courses (e.g. 14 days) have not been shown to improve outcomes in this uncomplicated setting and unnecessarily increase resistance selection pressure and adverse effects.', 3),
('d7000000-0000-0000-0000-000000000040', 'D', 'Antibiotics should be continued for a minimum of 6 weeks, as with endocarditis, given the presence of bacteraemia', false, 'Ruled out because prolonged 6-week courses are reserved for specific complicated infections such as endocarditis or deep-seated/endovascular infection, not uncomplicated Gram-negative bacteraemia from a urinary source with rapid response to treatment.', 4),
('d7000000-0000-0000-0000-000000000040', 'E', 'Duration should be guided solely by procalcitonin normalisation, with no defined minimum course length', false, 'Ruled out because while procalcitonin-guided algorithms can supplement clinical decision-making regarding antibiotic duration in some settings, a defined evidence-based duration (around 7 days) for uncomplicated Gram-negative bacteraemia remains the primary basis for the decision described here, rather than relying solely on a biomarker with no minimum course length.', 5),
('d7000000-0000-0000-0000-000000000041', 'A', 'Oral artemether-lumefantrine as first-line treatment given its convenience', false, 'Ruled out because oral therapy is inappropriate for severe malaria with impaired consciousness and multi-organ involvement; the patient requires parenteral treatment, and intravenous artesunate is specifically indicated for severe disease.', 1),
('d7000000-0000-0000-0000-000000000041', 'B', 'Intravenous quinine as the preferred first-line agent over artesunate', false, 'Ruled out because intravenous artesunate has been shown in major trials (e.g. SEAQUAMAT, AQUAMAT) to reduce mortality compared with intravenous quinine in severe malaria and is now the preferred first-line treatment where available, with quinine reserved as an alternative if artesunate is unavailable or contraindicated.', 2),
('d7000000-0000-0000-0000-000000000041', 'C', 'Delay antimalarial treatment until parasitaemia is reconfirmed on a repeat blood film the following morning', false, 'Ruled out because severe malaria is a medical emergency; treatment should be started immediately once the diagnosis is confirmed and severity criteria identified, not delayed for repeat testing, given the risk of rapid deterioration and death.', 3),
('d7000000-0000-0000-0000-000000000041', 'D', 'Exchange transfusion as the first-line intervention in preference to antimalarial therapy', false, 'Ruled out because exchange transfusion is not first-line therapy and is now rarely used; intravenous artesunate remains the primary first-line treatment, with exchange transfusion considered historically in specific circumstances of very high parasitaemia with adjunctive rather than primary intent, and is not supported by strong evidence.', 4),
('d7000000-0000-0000-0000-000000000041', 'E', 'Intravenous artesunate as first-line treatment for severe falciparum malaria', true, 'Correct. This presentation meets multiple WHO criteria for severe/complicated falciparum malaria (parasitaemia >10%, impaired consciousness, acute kidney injury, hyperlactataemia). Intravenous artesunate is the first-line treatment of choice for severe malaria, shown in large trials to reduce mortality compared with intravenous quinine, and should be started immediately without waiting for confirmation of complications beyond what is already evident, alongside supportive management of organ dysfunction and close monitoring (including for post-artesunate delayed haemolysis).', 5),
('d7000000-0000-0000-0000-000000000042', 'A', 'Increase the ceftriaxone dose and manage conservatively with bowel rest, without surgical referral', false, 'Ruled out because perforation with peritonitis and free air is a surgical emergency requiring prompt surgical intervention; antibiotic escalation alone, without addressing the perforation surgically, would be inadequate and dangerous.', 1),
('d7000000-0000-0000-0000-000000000042', 'B', 'Switch antibiotics to oral azithromycin given the possibility of ceftriaxone treatment failure', false, 'Ruled out because the acute deterioration described is due to a mechanical/surgical complication (perforation), not primary antibiotic treatment failure; the priority is urgent surgical referral, not simply switching antibiotic agents.', 2),
('d7000000-0000-0000-0000-000000000042', 'C', 'Arrange elective outpatient colonoscopy to investigate the abdominal pain further', false, 'Ruled out because this presentation (sudden severe pain, peritonism, free air under the diaphragm) indicates an acute surgical emergency requiring immediate inpatient surgical management, not elective outpatient investigation.', 3),
('d7000000-0000-0000-0000-000000000042', 'D', 'Urgent surgical assessment for likely typhoid-related intestinal perforation, alongside continued appropriate antibiotics and resuscitation for septic shock', true, $x$Correct. Intestinal perforation (typically of the terminal ileum, related to Peyer's patch ulceration) is a recognised, life-threatening complication of typhoid fever, presenting with sudden severe abdominal pain, peritonism and free intra-abdominal air on imaging. This requires urgent surgical assessment and likely operative management alongside continued appropriate antibiotic therapy and aggressive resuscitation for the resulting septic shock/peritonitis, and should not be managed conservatively.$x$, 4),
('d7000000-0000-0000-0000-000000000042', 'E', 'Administer antimotility agents such as loperamide to settle the abdominal symptoms', false, 'Ruled out because antimotility agents are inappropriate and potentially dangerous in this context; the presentation indicates perforation and peritonitis requiring urgent surgical management, not symptomatic control of presumed diarrhoeal symptoms.', 5),
('d7000000-0000-0000-0000-000000000043', 'A', 'Reassure and discharge with oral hydration advice, as she remains normotensive with warm peripheries', false, 'Ruled out because the described features (persistent vomiting, abdominal pain, rising haematocrit, falling platelets) are specific warning signs for severe dengue that require admission and monitoring even in the absence of current hypotension, as haemodynamic compromise can develop rapidly (dengue shock syndrome) once compensatory mechanisms fail.', 1),
('d7000000-0000-0000-0000-000000000043', 'B', 'Start non-steroidal anti-inflammatory drugs for symptomatic pain and fever control', false, 'Ruled out because NSAIDs (and aspirin) should be avoided in suspected dengue due to the bleeding risk associated with thrombocytopenia and platelet dysfunction; paracetamol is preferred for symptomatic control.', 2),
('d7000000-0000-0000-0000-000000000043', 'C', 'Admit for close monitoring and careful, judicious intravenous fluid resuscitation, recognising these as dengue warning signs indicating risk of progression to severe dengue with plasma leakage', true, 'Correct. Persistent vomiting, abdominal pain, and a rising haematocrit with falling platelet count are recognised WHO warning signs for progression to severe dengue, reflecting early plasma leakage (capillary permeability) even before hypotension develops. Management requires hospital admission, close haemodynamic monitoring, and carefully titrated intravenous fluid therapy, avoiding both under-resuscitation (progression to dengue shock syndrome) and over-resuscitation (fluid overload, particularly given ongoing capillary leak), rather than either simple reassurance or aggressive unmonitored fluid boluses.', 3),
('d7000000-0000-0000-0000-000000000043', 'D', 'Give a single large empirical bolus of intravenous fluid and discharge if she improves clinically within an hour', false, 'Ruled out because dengue with warning signs requires structured, ongoing monitoring (not a single bolus followed by discharge), given the risk of evolving plasma leakage and haemodynamic deterioration over the following hours to days, particularly around the time of defervescence.', 4),
('d7000000-0000-0000-0000-000000000043', 'E', 'Start empirical broad-spectrum antibiotics for presumed bacterial sepsis', false, 'Ruled out because this clinical picture (rash, thrombocytopenia, warning signs, travel history) is classic for dengue, a viral infection; antibiotics have no role unless a specific bacterial co-infection or complication is identified, and would delay appropriate dengue-specific monitoring and fluid management.', 5),
('d7000000-0000-0000-0000-000000000044', 'A', 'Chronic urinary schistosomiasis (Schistosoma haematobium), with the earlier acute illness representing Katayama syndrome; treatment is with praziquantel', true, 'Correct. Terminal-spined ova in urine confirm Schistosoma haematobium infection, causing chronic urinary schistosomiasis with haematuria and bladder/ureteric involvement (with long-term risk of squamous cell bladder carcinoma and ureteric obstruction/hydronephrosis if untreated). The earlier acute febrile illness with rash and wheeze after freshwater exposure is characteristic of Katayama syndrome, an acute hypersensitivity reaction to migrating schistosomulae. Treatment of established infection is with praziquantel, generally most effective once egg-laying (chronic) infection is established, sometimes combined with corticosteroids specifically if treating acute Katayama syndrome due to risk of exacerbating symptoms as organisms die.', 1),
('d7000000-0000-0000-0000-000000000044', 'B', 'Acute schistosomiasis (Katayama syndrome) currently active, requiring only supportive management with no antiparasitic treatment needed', false, 'Ruled out because the current presentation (chronic haematuria, terminal-spined ova in urine one year into symptoms, three years after exposure) represents established chronic urinary schistosomiasis, not acute Katayama syndrome, which occurred years earlier and was self-limiting; chronic infection requires specific antiparasitic treatment with praziquantel, not observation alone.', 2),
('d7000000-0000-0000-0000-000000000044', 'C', 'Bladder tuberculosis, requiring standard quadruple anti-tuberculous therapy', false, 'Ruled out because the specific finding of terminal-spined ova in urine is diagnostic of Schistosoma haematobium infection, not tuberculosis; while chronic schistosomiasis can occasionally coexist with or mimic other urinary pathology, the described microscopy finding directs specifically to schistosomiasis treatment.', 3),
('d7000000-0000-0000-0000-000000000044', 'D', 'Renal cell carcinoma requiring urgent oncological referral without further parasitological assessment', false, 'Ruled out because although chronic schistosomiasis is associated with increased long-term bladder cancer risk (squamous cell carcinoma), the immediate diagnosis based on the described urine microscopy is active schistosome infection requiring praziquantel treatment; malignancy would be a longer-term consideration on surveillance rather than the current diagnosis to act on immediately.', 4),
('d7000000-0000-0000-0000-000000000044', 'E', 'A urinary tract infection requiring a course of empirical antibiotics', false, 'Ruled out because the diagnostic finding described (terminal-spined ova) is specific for schistosomiasis and not explained by a bacterial urinary tract infection; antibiotics would not address the underlying parasitic infection.', 5),
('d7000000-0000-0000-0000-000000000045', 'A', 'Rabies vaccine course alone, as immunoglobulin is only required for facial or neck bites', false, 'Ruled out because rabies immunoglobulin is recommended for any category III exposure (bites breaking skin, or licks on broken skin/mucous membranes) in a previously unvaccinated individual, not restricted to facial or neck wounds specifically, given the risk of a fatal outcome if passive immunity is not provided while active immunisation develops.', 1),
('d7000000-0000-0000-0000-000000000045', 'B', 'Thorough wound cleansing (already performed), plus a full course of rabies vaccine and rabies immunoglobulin infiltrated around the wound, given no prior vaccination', true, $x$Correct. In an unvaccinated individual with a category III exposure (bite breaking the skin) from a high-risk animal in an endemic area, post-exposure prophylaxis requires thorough wound cleansing (ideally immediately, with soap and water/virucidal agent), a full course of rabies vaccine, and human rabies immunoglobulin, with as much as possible infiltrated directly into and around the wound, to provide passive immunity while active immunity develops from vaccination. This combination is essential given rabies' near-universal fatality once symptomatic.$x$, 2),
('d7000000-0000-0000-0000-000000000045', 'C', 'No specific post-exposure treatment is required if the wound has already been cleaned and there are no signs of infection', false, $x$Ruled out because wound cleaning alone is insufficient for a significant rabies exposure; specific post-exposure prophylaxis (vaccine plus immunoglobulin) is required given the near-uniformly fatal nature of established rabies and the inability to reliably assess the biting animal's rabies status in this setting.$x$, 3),
('d7000000-0000-0000-0000-000000000045', 'D', 'Observe the biting dog for ten days before deciding whether any treatment is needed', false, 'Ruled out because in a resource-limited or uncertain setting (as here, a stray dog while backpacking) where reliable observation of the animal cannot be assured, post-exposure prophylaxis should be started promptly rather than delayed pending observation, given the catastrophic consequences of delayed treatment if the animal proves rabid.', 4),
('d7000000-0000-0000-0000-000000000045', 'E', 'Administer rabies immunoglobulin alone without vaccination, as immunoglobulin provides sufficient long-term protection', false, 'Ruled out because immunoglobulin provides only short-term passive protection and must be combined with a full course of active vaccination to generate durable immunity; immunoglobulin alone is inadequate as definitive post-exposure prophylaxis.', 5),
('d7000000-0000-0000-0000-000000000046', 'A', 'Viral hepatitis A, requiring supportive management only with no role for antibiotics', false, 'Ruled out because while hepatitis A can cause jaundice, it does not typically cause this combination of severe myalgia, conjunctival suffusion and acute kidney injury, and does not explain the specific exposure history (floodwater); the clinical picture is much more consistent with leptospirosis, which requires specific antibiotic therapy.', 1),
('d7000000-0000-0000-0000-000000000046', 'B', 'Malaria, requiring intravenous artesunate as first-line treatment', false, 'Ruled out because although malaria remains an important differential in any returning febrile traveller, the specific combination of calf myalgia, conjunctival suffusion, and freshwater/floodwater exposure points strongly towards leptospirosis; appropriate travel and exposure history plus relevant testing should differentiate the two, and this scenario is designed to reflect leptospirosis rather than malaria.', 2),
('d7000000-0000-0000-0000-000000000046', 'C', $x$Leptospirosis (Weil's disease), requiring prompt intravenous antibiotics (e.g. benzylpenicillin or ceftriaxone) and aggressive supportive management of renal and hepatic dysfunction$x$, true, $x$Correct. This presentation (fever, severe myalgia especially calf pain, conjunctival suffusion, jaundice and acute kidney injury following floodwater/freshwater exposure) is classic for severe leptospirosis (Weil's disease). Management requires prompt intravenous antibiotic therapy (benzylpenicillin or a third-generation cephalosporin such as ceftriaxone are standard choices) alongside aggressive supportive care for renal impairment (which may require renal replacement therapy) and hepatic dysfunction; delay in treatment is associated with worse outcomes.$x$, 3),
('d7000000-0000-0000-0000-000000000046', 'D', 'Dengue haemorrhagic fever, requiring careful fluid balance without antibiotics', false, 'Ruled out because dengue serology is specifically stated to be negative, and the clinical picture (conjunctival suffusion, calf myalgia, floodwater exposure, renal and hepatic dysfunction) is more consistent with leptospirosis than dengue, which requires antibiotic therapy rather than supportive fluid management alone.', 4),
('d7000000-0000-0000-0000-000000000046', 'E', 'A self-limiting viral illness requiring only symptomatic treatment and outpatient follow-up', false, 'Ruled out because this presentation reflects severe, potentially life-threatening leptospirosis with organ dysfunction (renal failure, jaundice), requiring inpatient management with specific antibiotic therapy and close monitoring, not outpatient symptomatic care.', 5),
('d7000000-0000-0000-0000-000000000047', 'A', 'Treat with metronidazole (or tinidazole) as first-line therapy, followed by a luminal agent to eradicate intestinal cyst colonisation, reserving aspiration for large abscesses, diagnostic uncertainty, or failure to respond', true, 'Correct. Amoebic liver abscess is treated primarily with a tissue-active nitroimidazole (metronidazole or tinidazole), which is highly effective and usually avoids the need for drainage. This should be followed by a luminal agent (e.g. paromomycin or diloxanide furoate) to eradicate any residual intestinal colonisation and prevent transmission/recurrence, even though stool microscopy is negative here, as this does not reliably exclude colonisation. Aspiration/drainage is reserved for large abscesses at risk of rupture, left-lobe abscesses (risk of pericardial extension), diagnostic uncertainty, or failure to improve on medical therapy alone.', 1),
('d7000000-0000-0000-0000-000000000047', 'B', 'Immediate percutaneous or surgical drainage as first-line management for all liver abscesses of this size', false, 'Ruled out because medical therapy with metronidazole is typically effective as first-line treatment for amoebic liver abscess, even for reasonably large lesions; drainage is reserved for specific indications such as very large or left-lobe abscesses, risk of imminent rupture, or failure to respond to medical therapy, not applied routinely regardless of response.', 2),
('d7000000-0000-0000-0000-000000000047', 'C', 'Broad-spectrum antibiotics for presumed pyogenic liver abscess without amoebic-specific therapy', false, 'Ruled out because the strongly positive amoebic serology, together with the compatible clinical and radiological picture, supports a diagnosis of amoebic (not pyogenic) liver abscess, requiring specific amoebicidal therapy (metronidazole/tinidazole) rather than standard broad-spectrum antibacterial treatment alone.', 3),
('d7000000-0000-0000-0000-000000000047', 'D', 'No treatment is required, as amoebic liver abscess typically resolves spontaneously without intervention', false, 'Ruled out because untreated amoebic liver abscess can progress to serious complications, including rupture into the peritoneum, pleural space or pericardium; specific antiamoebic treatment is required, not observation alone.', 4),
('d7000000-0000-0000-0000-000000000047', 'E', 'Treat with a luminal agent alone (e.g. paromomycin), without any tissue-active antiamoebic therapy', false, 'Ruled out because luminal agents alone do not adequately treat invasive tissue disease such as liver abscess; a tissue-active agent (metronidazole or tinidazole) is required first to treat the invasive infection, with the luminal agent added afterward to address intestinal colonisation.', 5),
('d7000000-0000-0000-0000-000000000048', 'A', 'Chronic myeloid leukaemia; treatment with a tyrosine kinase inhibitor such as imatinib is indicated', false, 'Ruled out because although CML can cause marked splenomegaly, the specific bone marrow finding of intracellular amastigotes is diagnostic of visceral leishmaniasis, not a haematological malignancy; the clinical picture and diagnostic test both point specifically to kala-azar.', 1),
('d7000000-0000-0000-0000-000000000048', 'B', 'Malaria-associated hyperreactive splenomegaly syndrome, requiring long-term antimalarial chemoprophylaxis', false, 'Ruled out because although hyperreactive malarial splenomegaly can cause massive splenomegaly in endemic-area residents, the definitive finding of intracellular amastigotes on bone marrow specifically confirms visceral leishmaniasis rather than a malaria-related diagnosis.', 2),
('d7000000-0000-0000-0000-000000000048', 'C', 'Disseminated tuberculosis, requiring standard quadruple anti-tuberculous therapy', false, 'Ruled out because the bone marrow finding described (intracellular amastigotes) is specific for Leishmania infection, not tuberculosis; while disseminated TB is an important differential for fever, splenomegaly and pancytopenia, the diagnostic test result here confirms kala-azar.', 3),
('d7000000-0000-0000-0000-000000000048', 'D', 'Hairy cell leukaemia, requiring treatment with cladribine', false, 'Ruled out because hairy cell leukaemia is a distinct haematological malignancy diagnosed by specific blood/marrow immunophenotyping, not by finding intracellular amastigotes, which is the specific diagnostic feature of visceral leishmaniasis described here.', 4),
('d7000000-0000-0000-0000-000000000048', 'E', 'Visceral leishmaniasis (kala-azar); liposomal amphotericin B is an effective and well-tolerated first-line treatment option', true, 'Correct. The clinical picture (chronic fever/fatigue, massive splenomegaly, hepatomegaly, pancytopenia) with intracellular amastigotes on bone marrow aspirate is diagnostic of visceral leishmaniasis (kala-azar), endemic to the Indian subcontinent among other regions, caused by Leishmania donovani. Liposomal amphotericin B is a highly effective, well-tolerated first-line treatment, generally preferred over pentavalent antimonials in many settings due to a superior safety and efficacy profile, particularly in immunocompetent patients from the Indian subcontinent.', 5),
('d7000000-0000-0000-0000-000000000049', 'A', 'Proceed directly with corticosteroid therapy, as eosinophilia is a non-specific finding requiring no further action before starting treatment', false, 'Ruled out because unexplained eosinophilia in a patient from an endemic area about to start immunosuppressive therapy is a specific red flag for possible Strongyloides infection, and proceeding without addressing this risks precipitating potentially fatal hyperinfection syndrome.', 1),
('d7000000-0000-0000-0000-000000000049', 'B', 'Delay corticosteroid therapy indefinitely until all possible causes of eosinophilia have been fully excluded by extensive testing', false, 'Ruled out because while Strongyloides screening/treatment specifically should be prioritised before starting immunosuppression, an exhaustive, open-ended work-up of all possible eosinophilia causes is not required first; the specific, high-yield and clinically urgent action is targeted Strongyloides assessment and treatment given the imminent corticosteroid therapy.', 2),
('d7000000-0000-0000-0000-000000000049', 'C', 'Start prophylactic broad-spectrum antibiotics alongside corticosteroids to prevent hyperinfection syndrome', false, 'Ruled out because antibiotics do not treat or prevent Strongyloides hyperinfection, which is caused by autoinfective larvae rather than being a primary bacterial process (though secondary Gram-negative bacteraemia can complicate established hyperinfection); the specific and correct preventive measure is antihelminthic treatment (ivermectin) if Strongyloides infection is confirmed or presumed.', 3),
('d7000000-0000-0000-0000-000000000049', 'D', 'Screen for and, if positive, treat Strongyloides stercoralis infection (e.g. with serology plus stool testing, and ivermectin if confirmed) before starting corticosteroids', true, 'Correct. In any returning traveller or long-term resident of an endemic area with unexplained eosinophilia who requires corticosteroid or other immunosuppressive therapy, Strongyloides stercoralis infection must be actively excluded (or treated) first. Corticosteroids can precipitate life-threatening hyperinfection syndrome or disseminated strongyloidiasis by suppressing the immune response that normally controls autoinfective larvae, and this risk is often under-recognised because chronic strongyloidiasis can otherwise be asymptomatic or cause only vague symptoms for years.', 4),
('d7000000-0000-0000-0000-000000000049', 'E', 'Reassure the patient that Strongyloides infection is generally self-limiting and resolves without treatment even during immunosuppression', false, 'Ruled out because Strongyloides stercoralis is unique among intestinal helminths in its ability to cause chronic autoinfection persisting for decades, and immunosuppression (particularly corticosteroids) can trigger life-threatening hyperinfection or disseminated disease rather than the infection remaining benign or self-limiting.', 5),
('d7000000-0000-0000-0000-000000000050', 'A', 'Proceed with standard clinical assessment and routine venepuncture in an open bay, as malaria has already been excluded', false, 'Ruled out because malaria exclusion does not rule out viral haemorrhagic fever, and proceeding with standard, unprotected assessment risks nosocomial transmission of a potentially highly contagious and dangerous pathogen; strict isolation precautions should be implemented immediately given the concerning exposure history and clinical features.', 1),
('d7000000-0000-0000-0000-000000000050', 'B', 'Isolate the patient immediately in a single room with strict contact and droplet precautions, minimise staff contact and unnecessary blood tests, and urgently notify public health/infectious diseases and the relevant high-consequence infectious disease team', true, 'Correct. This presentation (fever, bleeding tendency, hypotension, relevant exposure history including close unprotected contact with an unwell person in a Lassa fever-endemic area of West Africa within the incubation period) raises a strong possibility of viral haemorrhagic fever (e.g. Lassa fever). Immediate strict isolation with appropriate personal protective equipment, minimisation of unnecessary investigations/staff exposure, and urgent liaison with public health authorities and specialist high-consequence infectious disease services is essential before further routine assessment, given the risk of person-to-person transmission and the need for specialised diagnostic and containment facilities.', 2),
('d7000000-0000-0000-0000-000000000050', 'C', 'Discharge with outpatient follow-up, as fever after African travel is usually due to a self-limiting viral illness', false, 'Ruled out because the combination of high-risk exposure, bleeding manifestations and haemodynamic compromise represents a medical emergency requiring urgent inpatient isolation and specialist assessment, not outpatient management.', 3),
('d7000000-0000-0000-0000-000000000050', 'D', 'Start empirical broad-spectrum antibiotics and manage on a general medical ward without isolation, pending further test results', false, 'Ruled out because antibiotics do not treat viral haemorrhagic fever, and managing the patient on an open ward without isolation precautions risks significant nosocomial transmission of a high-consequence infectious disease; isolation and specialist notification take priority over routine ward-based management.', 4),
('d7000000-0000-0000-0000-000000000050', 'E', 'Arrange non-urgent outpatient viral serology testing to be performed over the following week', false, 'Ruled out because this presentation requires urgent same-day specialist assessment and isolation given the risk of a high-consequence infectious disease, not delayed non-urgent outpatient testing.', 5)
insert into question_discriminators (question_id, discriminator_text, sort_order) values
('d7000000-0000-0000-0000-000000000001', 'AUC24/MIC (target approximately 400-600) is the pharmacokinetic-pharmacodynamic index most predictive of vancomycin efficacy and safety, and is now preferred over trough-only monitoring by major guidelines.', 1),
('d7000000-0000-0000-0000-000000000001', 'Trough-only monitoring can both under- and over-estimate true drug exposure, especially in patients with rapidly changing renal function, obesity, or intermittent haemodialysis schedules.', 2),
('d7000000-0000-0000-0000-000000000001', 'Bayesian dosing software uses population pharmacokinetic models plus a small number of measured levels to individualise dosing more precisely than trough targets alone.', 3),
('d7000000-0000-0000-0000-000000000002', $x$The majority of patients labelled 'penicillin allergic' are not truly allergic, and low-risk histories (mild, delayed, non-blistering rash without systemic features) can usually be safely de-labelled.$x$, 1),
('d7000000-0000-0000-0000-000000000002', 'De-labelling improves outcomes by enabling first-line beta-lactam therapy, which is often more effective and less toxic than alternative regimens, and reduces broad-spectrum antibiotic use.', 2),
('d7000000-0000-0000-0000-000000000002', 'Desensitisation (rather than de-labelling) is reserved for patients with a confirmed or high-risk allergy for whom a beta-lactam is essential and no suitable alternative exists.', 3),
('d7000000-0000-0000-0000-000000000003', 'Echinocandins are first-line therapy for candidaemia in most adults, especially those who are critically ill, haemodynamically unstable, or recently azole-exposed.', 1),
('d7000000-0000-0000-0000-000000000003', 'Source control (removal of infected central venous catheters) is a critical, independent determinant of outcome in candidaemia and should occur promptly alongside antifungal therapy.', 2),
('d7000000-0000-0000-0000-000000000003', 'Step-down to fluconazole can be considered once the patient is clinically stable, cultures have cleared, and the isolate is confirmed fluconazole-susceptible.', 3),
('d7000000-0000-0000-0000-000000000004', 'Long-acting lipoglycopeptides (dalbavancin, oritavancin) allow completion of extended Gram-positive bone/joint infection treatment with minimal infusions, useful when OPAT infrastructure or venous access is limited.', 1),
('d7000000-0000-0000-0000-000000000004', 'Osteomyelitis treatment duration is typically prolonged (often around six weeks) and depends on surgical source control, causative organism and clinical/radiological response.', 2),
('d7000000-0000-0000-0000-000000000004', 'OPAT decisions must weigh antimicrobial spectrum, pharmacokinetics, patient factors (access, home support) and available local infrastructure, not default automatically to prolonged inpatient care.', 3),
('d7000000-0000-0000-0000-000000000005', 'Extended-interval (once-daily) aminoglycoside dosing is monitored with a single nomogram-timed level (commonly 6-14 hours post-dose), not conventional peak/trough sampling.', 1),
('d7000000-0000-0000-0000-000000000005', $x$The dosing interval (24, 36 or 48 hourly) is adjusted according to where the level falls on the validated nomogram, reflecting the patient's drug clearance.$x$, 2),
('d7000000-0000-0000-0000-000000000005', 'Renal function should be monitored throughout an aminoglycoside course, as nephrotoxicity risk increases with treatment duration and cumulative exposure even when baseline function is normal.', 3),
('d7000000-0000-0000-0000-000000000006', 'Avibactam is a novel non-beta-lactam beta-lactamase inhibitor active against class A carbapenemases (including KPC) and class C/some class D enzymes, but not against metallo-beta-lactamases (e.g. NDM, VIM, IMP).', 1),
('d7000000-0000-0000-0000-000000000006', 'Carbapenemase-producing organisms require carbapenemase class identification (serine vs metallo-beta-lactamase) as this determines which novel beta-lactam/beta-lactamase inhibitor combination will be effective.', 2),
('d7000000-0000-0000-0000-000000000006', 'Colistin, while historically used for carbapenem-resistant Gram-negative infections, has largely been superseded where possible by better-tolerated, more effective novel agents matched to the resistance mechanism.', 3),
('d7000000-0000-0000-0000-000000000007', 'Rifampicin is a potent CYP450 inducer and its co-administration with voriconazole is contraindicated due to markedly reduced antifungal exposure and risk of treatment failure.', 1),
('d7000000-0000-0000-0000-000000000007', 'Voriconazole has a narrow therapeutic index and unpredictable, non-linear pharmacokinetics (partly due to CYP2C19 polymorphism), making therapeutic drug monitoring essential during treatment of invasive fungal infection.', 2),
('d7000000-0000-0000-0000-000000000007', 'When treating concurrent tuberculosis/mycobacterial disease and invasive fungal infection, drug interaction potential must be proactively reviewed before finalising both regimens, often requiring specialist microbiology/infectious diseases input.', 3),
('d7000000-0000-0000-0000-000000000008', 'Faecal microbiota transplantation is recommended after multiple recurrences of C. difficile infection, as it restores colonisation resistance and has high efficacy in preventing further relapse.', 1),
('d7000000-0000-0000-0000-000000000008', 'Fidaxomicin (with its narrower spectrum and reduced impact on gut microbiota) and monoclonal antibody adjuncts such as bezlotoxumab are alternative strategies used to reduce recurrence risk, particularly at first recurrence.', 2),
('d7000000-0000-0000-0000-000000000008', 'Colectomy is reserved for fulminant/complicated C. difficile colitis (toxic megacolon, perforation, refractory shock), not for uncomplicated but recurrent disease.', 3),
('d7000000-0000-0000-0000-000000000009', 'Desensitisation is used when a confirmed, clinically significant (typically IgE-mediated) allergy exists and the allergenic drug is essential because no equally effective alternative is available.', 1),
('d7000000-0000-0000-0000-000000000009', 'Desensitisation induces temporary tolerance through incremental dosing under close monitoring; it must be followed immediately by the therapeutic course, as tolerance is lost once the drug is stopped.', 2),
('d7000000-0000-0000-0000-000000000009', 'This differs from de-labelling/graded challenge, which is used for patients whose allergy history is low-risk or unconfirmed, with the aim of disproving true allergy rather than inducing temporary tolerance to a confirmed one.', 3),
('d7000000-0000-0000-0000-000000000010', $x$Linezolid's weak monoamine oxidase inhibitor activity means concomitant serotonergic drugs (SSRIs, SNRIs, tramadol, triptans, MAOIs) carry a risk of serotonin syndrome, requiring careful assessment before co-prescribing.$x$, 1),
('d7000000-0000-0000-0000-000000000010', 'Linezolid-associated thrombocytopenia and myelosuppression are more common with prolonged courses (beyond around two weeks) and require monitoring of full blood counts during treatment.', 2),
('d7000000-0000-0000-0000-000000000010', 'Unlike vancomycin, linezolid does not require renal dose adjustment and has excellent oral bioavailability, making it well suited for renal impairment and IV-to-oral switch strategies when otherwise appropriate.', 3),
('d7000000-0000-0000-0000-000000000011', 'In HIV/TB co-infection with CD4 <50 cells/microL, early ART (within about 2 weeks of starting TB treatment) reduces mortality despite higher IRIS risk; with CD4 ≥50, ART can be deferred to 8-12 weeks to reduce IRIS risk.', 1),
('d7000000-0000-0000-0000-000000000011', 'TB meningitis is an exception: early ART increases mortality due to CNS-IRIS-related complications, so a more cautious, delayed approach (guided by specialist input) is used regardless of CD4 count.', 2),
('d7000000-0000-0000-0000-000000000011', 'TB-associated IRIS presents as a paradoxical worsening of TB symptoms/signs (fever, lymphadenopathy, worsening radiological findings) after starting ART, and is managed with continued antimicrobial therapy plus corticosteroids in more severe cases rather than stopping ART.', 3),
('d7000000-0000-0000-0000-000000000012', 'Cryptococcal meningitis is a key exception to early-ART strategies: ART is deferred approximately 4-6 weeks after starting antifungal induction therapy to reduce IRIS-related mortality.', 1),
('d7000000-0000-0000-0000-000000000012', 'Cryptococcal IRIS can cause dangerous raised intracranial pressure and clinical deterioration; management of raised intracranial pressure in cryptococcal meningitis includes therapeutic lumbar punctures/CSF drainage rather than corticosteroids or mannitol as first-line measures.', 2),
('d7000000-0000-0000-0000-000000000012', 'Amphotericin B plus flucytosine induction, followed by fluconazole consolidation and maintenance, is the standard antifungal regimen for HIV-associated cryptococcal meningitis.', 3),
('d7000000-0000-0000-0000-000000000013', 'In HIV patients with low CD4 counts, positive toxoplasma serology and typical ring-enhancing CNS lesions, empirical anti-toxoplasma therapy is standard, with clinical/radiological response assessed at 10-14 days.', 1),
('d7000000-0000-0000-0000-000000000013', 'Failure to respond to empirical toxoplasmosis treatment should prompt consideration of alternative diagnoses, especially primary CNS lymphoma (associated with EBV), and further investigation including biopsy.', 2),
('d7000000-0000-0000-0000-000000000013', 'As with other opportunistic infections, antiretroviral therapy timing after starting toxoplasmosis treatment should balance immune reconstitution benefits against IRIS risk, generally not deferred as long as in cryptococcal meningitis.', 3),
('d7000000-0000-0000-0000-000000000014', 'CMV retinitis requires prompt anti-CMV therapy (valganciclovir/ganciclovir/foscarnet, with intravitreal options for severe or sight-threatening disease) and urgent ophthalmology assessment to prevent irreversible vision loss.', 1),
('d7000000-0000-0000-0000-000000000014', 'CMV immune recovery uveitis is a recognised IRIS phenomenon that can occur after starting ART in patients with CMV retinitis, causing inflammation-mediated visual complications despite viral control.', 2),
('d7000000-0000-0000-0000-000000000014', $x$CMV retinitis typically occurs at very low CD4 counts (usually below 50-100 cells/microL) and its characteristic fundoscopic appearance (haemorrhages and retinal whitening, described as 'pizza pie' or 'cottage cheese and ketchup') usually allows clinical diagnosis without biopsy.$x$, 3),
('d7000000-0000-0000-0000-000000000015', 'Suboptimal adherence is the most common cause of virological failure on antiretroviral therapy and must be actively assessed and supported alongside any investigation for resistance.', 1),
('d7000000-0000-0000-0000-000000000015', 'Genotypic resistance testing must be performed while the patient remains on the failing regimen, as resistant variants can revert to below detectable levels once drug selective pressure is removed.', 2),
('d7000000-0000-0000-0000-000000000015', 'Regimen switches after virological failure should be guided by resistance test results (and prior treatment history/cumulative resistance) to select an effective new combination, rather than empirical drug changes.', 3),
('d7000000-0000-0000-0000-000000000016', 'Rifampicin is a potent inducer of UGT1A1 (and CYP3A4), reducing plasma concentrations of dolutegravir; this is managed by increasing dolutegravir to twice-daily dosing during co-administration.', 1),
('d7000000-0000-0000-0000-000000000016', 'Drug interaction assessment is essential whenever initiating rifampicin-based TB treatment in a patient on antiretroviral therapy, as several antiretroviral classes (protease inhibitors, some integrase inhibitors, NNRTIs) are significantly affected.', 2),
('d7000000-0000-0000-0000-000000000016', 'Rifabutin is a less potent enzyme inducer than rifampicin and can be substituted in specific interaction scenarios (e.g. with certain protease inhibitors), but does not eliminate the need to review each antiretroviral component individually.', 3),
('d7000000-0000-0000-0000-000000000017', 'Adjunctive corticosteroids are indicated in PCP with significant hypoxaemia (PaO2 <9.3 kPa on room air, or alveolar-arterial gradient >35 mmHg) and should be started early (within 72 hours) alongside antimicrobial therapy.', 1),
('d7000000-0000-0000-0000-000000000017', 'Co-trimoxazole remains first-line therapy for PCP; alternatives (IV pentamidine, clindamycin plus primaquine, atovaquone) are reserved for intolerance, allergy or treatment failure.', 2),
('d7000000-0000-0000-0000-000000000017', 'Corticosteroid benefit in PCP relates to reducing treatment-induced inflammatory lung injury as organisms die, rather than treating the infection itself, and is tapered over about three weeks.', 3),
('d7000000-0000-0000-0000-000000000018', 'PML has no proven specific antiviral treatment; immune reconstitution (via antiretroviral therapy in HIV, or withdrawal of causative immunosuppressive drugs in other contexts) is the key management strategy.', 1),
('d7000000-0000-0000-0000-000000000018', 'PML-IRIS can cause paradoxical clinical and radiological worsening after starting ART as immune function recovers, and may require corticosteroids in severe cases despite the underlying rationale for starting ART.', 2),
('d7000000-0000-0000-0000-000000000018', 'PML classically causes multifocal, asymmetric, non-enhancing white matter lesions without significant mass effect on MRI, and is confirmed by CSF JC virus PCR, distinguishing it from other HIV-associated CNS processes.', 3),
('d7000000-0000-0000-0000-000000000019', 'Disseminated MAC is treated with combination therapy (macrolide plus ethambutol, +/- a third agent in severe disease), as macrolide monotherapy risks rapid resistance development.', 1),
('d7000000-0000-0000-0000-000000000019', 'Antiretroviral therapy is central to long-term control of disseminated MAC via immune reconstitution, and should be started promptly (generally around 2 weeks) after starting MAC treatment, with monitoring for IRIS.', 2),
('d7000000-0000-0000-0000-000000000019', 'Primary MAC prophylaxis (e.g. azithromycin) is considered in patients with very low CD4 counts (traditionally below 50 cells/microL) not on effective ART, but is distinct from treatment-dose therapy for confirmed active disease.', 3),
('d7000000-0000-0000-0000-000000000020', 'HIV post-exposure prophylaxis should be started as soon as possible after a significant exposure, ideally within an hour and no later than 72 hours, using a three-drug antiretroviral regimen for around 28 days.', 1),
('d7000000-0000-0000-0000-000000000020', $x$Risk assessment for occupational exposure considers the type of injury (percutaneous vs mucocutaneous), device (hollow-bore needle higher risk), presence of visible blood, and the source patient's HIV status/viral control, but starting PEP should not be delayed pending full confirmation when risk appears significant.$x$, 2),
('d7000000-0000-0000-0000-000000000020', 'Baseline and follow-up testing (HIV, hepatitis B and C serology, with repeat testing at appropriate intervals) and hepatitis B post-exposure management (vaccination/immunoglobulin as indicated) should be arranged alongside HIV PEP as part of comprehensive occupational exposure management.', 3),
('d7000000-0000-0000-0000-000000000021', 'In catheter-associated UTI, biofilm on the indwelling catheter surface acts as a persistent nidus of infection; catheter removal (if no longer needed) or replacement (if still required) improves treatment response alongside targeted antibiotics.', 1),
('d7000000-0000-0000-0000-000000000021', 'Asymptomatic bacteriuria in catheterised patients should not be treated with antibiotics; treatment is reserved for those with systemic or localising symptoms consistent with infection.', 2),
('d7000000-0000-0000-0000-000000000021', 'CAUTI prevention strategies focus on avoiding unnecessary catheterisation, prompt removal once no longer needed, and aseptic insertion/maintenance technique, rather than routine antiseptic irrigation.', 3),
('d7000000-0000-0000-0000-000000000022', 'Catheter salvage with systemic antibiotics plus antibiotic lock therapy can be attempted for low-virulence organisms (e.g. coagulase-negative staphylococci) in stable patients with valuable, hard-to-replace lines, whereas Staphylococcus aureus and Candida bloodstream infections generally mandate catheter removal.', 1),
('d7000000-0000-0000-0000-000000000022', 'Differential time to positivity (catheter blood culture becoming positive at least two hours before a paired peripheral sample) supports a diagnosis of catheter-related bloodstream infection without requiring catheter removal for culture.', 2),
('d7000000-0000-0000-0000-000000000022', 'Guidewire exchange of an infected catheter is generally avoided because it can seed the new catheter via the existing infected tract; true removal and re-siting, or salvage in situ, are preferred depending on organism and severity.', 3),
('d7000000-0000-0000-0000-000000000023', 'Necrotising fasciitis is a surgical emergency: urgent, often repeated, surgical debridement is the primary determinant of survival and should not be delayed for imaging or a trial of antibiotics when clinical suspicion is high.', 1),
('d7000000-0000-0000-0000-000000000023', 'Broad-spectrum antibiotics covering streptococci, staphylococci, Gram-negative organisms and anaerobes (often with clindamycin for its antitoxin/protein-synthesis-inhibiting effect against toxin-producing strains) are given alongside, not instead of, surgery.', 2),
('d7000000-0000-0000-0000-000000000023', 'Clinical clues suggestive of necrotising fasciitis over simple cellulitis/surgical site infection include pain out of proportion to signs, crepitus, rapidly spreading skin changes, systemic toxicity and gas on imaging.', 3),
('d7000000-0000-0000-0000-000000000024', 'Antimicrobial de-escalation from broad empirical therapy to narrow, pathogen-directed treatment once culture and susceptibility results are available is a core antimicrobial stewardship principle in VAP and other serious infections.', 1),
('d7000000-0000-0000-0000-000000000024', 'De-escalation reduces resistance selection pressure, adverse effects, and healthcare-associated complications (e.g. C. difficile infection) while maintaining clinical efficacy when guided by reliable microbiological data and clinical improvement.', 2),
('d7000000-0000-0000-0000-000000000024', 'Total duration of antibiotic therapy for VAP is typically defined (often around 7 days for uncomplicated cases with good clinical response) rather than continued indefinitely once the causative organism responds to targeted treatment.', 3),
('d7000000-0000-0000-0000-000000000025', 'C. difficile spores are resistant to alcohol-based hand sanitisers; soap and water handwashing is required for effective mechanical spore removal.', 1),
('d7000000-0000-0000-0000-000000000025', 'Environmental decontamination during a C. difficile outbreak requires sporicidal agents (commonly chlorine-based/hypochlorite solutions), as standard detergents are inadequate against spores.', 2),
('d7000000-0000-0000-0000-000000000025', 'Outbreak control also relies on contact precautions/isolation of symptomatic patients and antimicrobial stewardship to reduce use of high-risk antibiotics (e.g. broad-spectrum cephalosporins, fluoroquinolones, clindamycin) that predispose to C. difficile infection.', 3),
('d7000000-0000-0000-0000-000000000026', 'Recent overseas healthcare contact (especially prolonged hospitalisation) is a recognised risk factor for carriage of multidrug-resistant organisms, including carbapenem-resistant Enterobacteriaceae, warranting targeted screening on admission.', 1),
('d7000000-0000-0000-0000-000000000026', 'Pre-emptive isolation with contact precautions while screening results are pending is standard practice for high-risk patients, given the significant consequences of unrecognised CRE transmission within a healthcare facility.', 2),
('d7000000-0000-0000-0000-000000000026', 'CRE screening and isolation strategies are distinct from, and additional to, routine MRSA screening protocols used for general hospital admissions.', 3),
('d7000000-0000-0000-0000-000000000027', 'Pre-operative MRSA decolonisation (topical nasal mupirocin plus chlorhexidine body washing) reduces surgical site infection risk in known carriers undergoing elective surgery, particularly prosthetic joint implantation.', 1),
('d7000000-0000-0000-0000-000000000027', 'Peri-operative antibiotic prophylaxis should be adjusted in known MRSA carriers to ensure adequate anti-MRSA activity (e.g. adding or substituting a glycopeptide), rather than relying on standard prophylaxis regimens designed for methicillin-susceptible organisms.', 2),
('d7000000-0000-0000-0000-000000000027', 'Prosthetic joint infection with MRSA carries substantial morbidity (often requiring prolonged antibiotics and revision surgery), making pre-operative risk reduction strategies particularly important before joint replacement surgery.', 3),
('d7000000-0000-0000-0000-000000000028', 'DAIR (debridement, antibiotics, implant retention) is preferred for acute prosthetic joint infection with a well-fixed prosthesis, no sinus tract, and short symptom duration, combined with prolonged targeted antibiotics.', 1),
('d7000000-0000-0000-0000-000000000028', $x$Rifampicin combination therapy is often used for staphylococcal prosthetic joint infection because of rifampicin's activity against biofilm-associated organisms, but only after adequate surgical source control to reduce resistance risk.$x$, 2),
('d7000000-0000-0000-0000-000000000028', 'Two-stage revision is generally reserved for chronic infection, prosthesis loosening, sinus tract formation, or DAIR failure, reflecting the greater difficulty of eradicating established biofilm infection in these situations.', 3),
('d7000000-0000-0000-0000-000000000029', $x$Norovirus outbreaks on healthcare wards are managed with ward closure to new admissions/transfers, isolation/cohorting of symptomatic patients, and enhanced environmental cleaning, given the virus's high infectivity and environmental persistence.$x$, 1),
('d7000000-0000-0000-0000-000000000029', 'Soap and water hand hygiene is preferred over alcohol-based gel during norovirus outbreaks, as alcohol has reduced efficacy against this non-enveloped virus.', 2),
('d7000000-0000-0000-0000-000000000029', 'Norovirus management is supportive (hydration, symptom control); there is no specific antiviral or antibiotic treatment, and antibiotics have no role unless a secondary bacterial complication is specifically identified.', 3),
('d7000000-0000-0000-0000-000000000030', $x$Hepatitis B post-exposure management depends on the exposed individual's vaccination and antibody response status: known responders need only a booster, while non-responders or those with unknown/inadequate response require hepatitis B immunoglobulin plus vaccine booster, particularly with a high-risk (HBeAg positive, high viral load) source.$x$, 1),
('d7000000-0000-0000-0000-000000000030', 'Vaccine-induced immunity to hepatitis B can wane over time, and anti-HBs levels should be checked when response status is uncertain following a significant exposure, rather than assuming ongoing protection from a vaccine course completed years earlier.', 2),
('d7000000-0000-0000-0000-000000000030', 'This differs from HIV occupational exposure, where multi-drug antiretroviral post-exposure prophylaxis (not immunoglobulin) is the mainstay of prevention, and from hepatitis C, for which no effective post-exposure prophylaxis currently exists and follow-up testing/early treatment if seroconversion occurs is the main strategy.', 3),
('d7000000-0000-0000-0000-000000000031', 'Noradrenaline is the first-line vasopressor in septic shock, targeting a mean arterial pressure of at least 65 mmHg once initial fluid resuscitation has been given.', 1),
('d7000000-0000-0000-0000-000000000031', 'Dopamine is no longer recommended as first-line therapy in septic shock due to increased arrhythmia risk and inferior outcomes compared with noradrenaline in trial data.', 2),
('d7000000-0000-0000-0000-000000000031', 'Source control (e.g. drainage of an abscess, debridement, or removal of an infected device) is a time-critical intervention in septic shock and should proceed without unnecessary delay, in parallel with haemodynamic resuscitation.', 3),
('d7000000-0000-0000-0000-000000000032', $x$All patients with Staphylococcus aureus bacteraemia should be assessed for infective endocarditis (clinically and with echocardiography), given the organism's strong propensity for endovascular seeding.$x$, 1),
('d7000000-0000-0000-0000-000000000032', 'Duration of therapy for Staphylococcus aureus bacteraemia depends on whether it is classified as uncomplicated versus complicated (endocarditis, metastatic foci, persistent bacteraemia, prosthetic material, delayed clearance), with complicated disease requiring substantially longer treatment.', 2),
('d7000000-0000-0000-0000-000000000032', 'Source control (removal of the infected focus, e.g. an infected line) and confirmation of blood culture clearance are essential components of managing Staphylococcus aureus bacteraemia alongside imaging assessment.', 3),
('d7000000-0000-0000-0000-000000000033', 'Heart failure due to valve dysfunction is one of the strongest indications for early (often urgent) surgery in infective endocarditis, as delay risks further haemodynamic deterioration and death.', 1),
('d7000000-0000-0000-0000-000000000033', 'Other key indications for surgery in endocarditis include uncontrolled infection (perivalvular abscess, persistent bacteraemia despite appropriate therapy, fungal or highly resistant organisms) and prevention of embolism (large, mobile vegetations, particularly with prior embolic events).', 2),
('d7000000-0000-0000-0000-000000000033', $x$Streptococcus gallolyticus (bovis) bacteraemia is strongly associated with colorectal neoplasia, and colonoscopy should be arranged as part of the patient's overall work-up once acutely stabilised.$x$, 3),
('d7000000-0000-0000-0000-000000000034', 'Febrile neutropenia requires empirical broad-spectrum intravenous antibiotics with Gram-negative (including Pseudomonas) cover within one hour of presentation, regardless of how clinically well the patient appears initially.', 1),
('d7000000-0000-0000-0000-000000000034', 'Blood cultures (peripheral and, where present, from central venous catheters) should be taken but must not delay the timely administration of empirical antibiotics.', 2),
('d7000000-0000-0000-0000-000000000034', 'Persistent fever despite 4-7 days of appropriate broad-spectrum antibacterial therapy in neutropenic patients prompts consideration of empirical antifungal therapy, rather than antifungals being first-line initial treatment.', 3),
('d7000000-0000-0000-0000-000000000035', 'Septic arthritis is a medical/surgical emergency requiring urgent joint aspiration and prompt empirical intravenous antibiotics, without waiting for culture confirmation, given the risk of rapid, irreversible joint destruction.', 1),
('d7000000-0000-0000-0000-000000000035', 'Orthopaedic involvement is essential in septic arthritis, as surgical washout/debridement is frequently required in addition to antibiotic therapy, particularly in systemically unwell patients or those failing to improve with aspiration and antibiotics alone.', 2),
('d7000000-0000-0000-0000-000000000035', 'Synovial fluid analysis (microscopy, culture, crystal examination) helps differentiate septic arthritis from crystal arthropathy, though clinical suspicion of infection should not be dismissed while awaiting results if the presentation is systemically concerning.', 3),
('d7000000-0000-0000-0000-000000000036', 'Toxic shock syndrome is a toxin-mediated (superantigen) illness, classically associated with retained tampons/foreign bodies and toxigenic Staphylococcus aureus (TSST-1) or group A Streptococcus, and blood cultures are frequently negative.', 1),
('d7000000-0000-0000-0000-000000000036', 'Management requires prompt source control (removal of the causative foreign body/drainage of any focus), aggressive supportive care for multi-organ dysfunction, and antibiotics including an agent with anti-toxin (protein synthesis inhibiting) activity such as clindamycin, alongside an antistaphylococcal/antistreptococcal agent.', 2),
('d7000000-0000-0000-0000-000000000036', 'Toxic shock syndrome should be considered in any patient with fever, diffuse erythroderma, hypotension and multi-organ dysfunction, particularly with a relevant risk factor such as tampon use, wound packing, or post-surgical/postpartum infection.', 3),
('d7000000-0000-0000-0000-000000000037', 'In septic shock inadequately controlled on noradrenaline alone, adding vasopressin as a second agent is recommended, potentially allowing catecholamine dose reduction.', 1),
('d7000000-0000-0000-0000-000000000037', 'Dopamine is not preferred over noradrenaline in septic shock due to increased arrhythmia risk and less favourable outcomes in trial evidence.', 2),
('d7000000-0000-0000-0000-000000000037', 'Ongoing fluid administration in septic shock should be guided by dynamic assessment of fluid responsiveness rather than repeated fixed boluses once initial resuscitation targets have been met.', 3),
('d7000000-0000-0000-0000-000000000038', 'Candida glabrata frequently shows reduced or variable susceptibility to fluconazole, making echinocandins the preferred first-line agents for candidaemia caused by this species.', 1),
('d7000000-0000-0000-0000-000000000038', 'Source control (prompt removal of infected central venous catheters) is essential in catheter-associated candidaemia and significantly influences outcomes alongside systemic antifungal therapy.', 2),
('d7000000-0000-0000-0000-000000000038', 'Species identification in candidaemia has direct treatment implications, as susceptibility patterns vary significantly between Candida species (e.g. C. albicans generally fluconazole-susceptible, C. glabrata and C. auris more often resistant).', 3),
('d7000000-0000-0000-0000-000000000039', 'Overwhelming post-splenectomy infection (OPSI) is a life-threatening emergency, classically caused by encapsulated organisms (Streptococcus pneumoniae most commonly, also Haemophilus influenzae type b and Neisseria meningitidis), and requires immediate empirical antibiotics without diagnostic delay.', 1),
('d7000000-0000-0000-0000-000000000039', 'Asplenic/hyposplenic patients carry a lifelong increased infection risk and should receive appropriate vaccination (pneumococcal, Haemophilus influenzae type b, meningococcal, annual influenza) and patient education on seeking urgent medical attention for any fever.', 2),
('d7000000-0000-0000-0000-000000000039', $x$Some guidelines recommend that asplenic patients carry emergency 'standby' antibiotics to take immediately if they develop fever before reaching medical care, reflecting how rapidly OPSI can progress.$x$, 3),
('d7000000-0000-0000-0000-000000000040', 'Shorter antibiotic courses (around 7 days) are now supported by trial evidence for uncomplicated Gram-negative bacteraemia (including urinary source) with rapid clinical response and adequate source control.', 1),
('d7000000-0000-0000-0000-000000000040', 'Complicating features that would warrant a longer course include undrained collections, obstruction, immunosuppression, endovascular/prosthetic material involvement, or slow clinical/microbiological response.', 2),
('d7000000-0000-0000-0000-000000000040', 'Minimising unnecessary antibiotic duration is a core antimicrobial stewardship principle, reducing resistance selection, adverse drug effects, and healthcare-associated complications such as Clostridioides difficile infection.', 3),
('d7000000-0000-0000-0000-000000000041', 'Intravenous artesunate is first-line treatment for severe falciparum malaria, shown to reduce mortality compared with intravenous quinine in major randomised trials.', 1),
('d7000000-0000-0000-0000-000000000041', 'Severe malaria criteria include impaired consciousness, acute kidney injury, pulmonary oedema/ARDS, significant acidosis/hyperlactataemia, severe anaemia, hypoglycaemia, spontaneous bleeding/DIC, shock, and parasitaemia above a defined threshold (commonly cited around 10%).', 2),
('d7000000-0000-0000-0000-000000000041', 'Patients treated with intravenous artesunate should be monitored for post-artesunate delayed haemolysis, which can occur one to several weeks after treatment and requires follow-up full blood count monitoring.', 3),
('d7000000-0000-0000-0000-000000000042', $x$Intestinal perforation (typically terminal ileal, related to Peyer's patch ulceration) is a life-threatening complication of typhoid fever presenting with acute abdominal pain, peritonism and free air on imaging, requiring urgent surgical management.$x$, 1),
('d7000000-0000-0000-0000-000000000042', 'Typhoid fever classically presents with a stepwise fever, relative bradycardia, headache and abdominal symptoms, with rising antimicrobial resistance (including fluoroquinolone resistance in many endemic regions) influencing empirical antibiotic choice, commonly ceftriaxone or azithromycin.', 2),
('d7000000-0000-0000-0000-000000000042', 'Other recognised complications of enteric fever include gastrointestinal haemorrhage, typhoid encephalopathy, and (rarely) myocarditis, reflecting the systemic nature of severe Salmonella Typhi infection.', 3),
('d7000000-0000-0000-0000-000000000043', 'WHO dengue warning signs (persistent vomiting, abdominal pain, mucosal bleeding, lethargy, liver enlargement, rising haematocrit with falling platelets, clinical fluid accumulation) indicate risk of progression to severe dengue and require hospital admission and close monitoring.', 1),
('d7000000-0000-0000-0000-000000000043', 'Fluid management in dengue with warning signs must be carefully judicious, balancing the risk of dengue shock syndrome (from capillary leak) against fluid overload, and is often most critical around the time of defervescence (typically days 3-7).', 2),
('d7000000-0000-0000-0000-000000000043', 'NSAIDs and aspirin should be avoided in suspected dengue due to bleeding risk from thrombocytopenia and platelet dysfunction; paracetamol is the preferred antipyretic/analgesic.', 3),
('d7000000-0000-0000-0000-000000000044', 'Schistosoma haematobium causes chronic urinary schistosomiasis (haematuria, bladder/ureteric involvement, long-term bladder squamous cell carcinoma risk); diagnosis is supported by terminal-spined ova on urine microscopy.', 1),
('d7000000-0000-0000-0000-000000000044', 'Katayama syndrome is an acute hypersensitivity reaction to migrating schistosomulae, occurring weeks after freshwater exposure, with fever, urticaria, wheeze and eosinophilia, and is distinct from the chronic egg-related disease that develops later.', 2),
('d7000000-0000-0000-0000-000000000044', 'Praziquantel is the treatment of choice for schistosomiasis, though it is most effective against mature worms/established infection; timing and adjunctive corticosteroids may be considered specifically when treating acute Katayama syndrome.', 3),
('d7000000-0000-0000-0000-000000000045', 'Category III rabies exposures (bites breaking skin, or contamination of mucous membranes/broken skin with saliva) in previously unvaccinated individuals require both a full vaccine course and rabies immunoglobulin, with immunoglobulin infiltrated around the wound where possible.', 1),
('d7000000-0000-0000-0000-000000000045', 'Wound cleansing (thorough washing with soap/water or a virucidal agent) is a critical first step in rabies post-exposure management and reduces the viral inoculum, but does not replace the need for specific immunoprophylaxis.', 2),
('d7000000-0000-0000-0000-000000000045', $x$Once clinical rabies develops, the disease is almost universally fatal, which is why prompt, complete post-exposure prophylaxis is essential rather than a 'wait and observe' approach when the biting animal's status cannot be reliably confirmed.$x$, 3),
('d7000000-0000-0000-0000-000000000046', $x$Leptospirosis classically presents with fever, severe myalgia (especially calves), conjunctival suffusion, and in severe disease (Weil's disease), jaundice and acute kidney injury, typically following exposure to floodwater or freshwater contaminated with animal urine.$x$, 1),
('d7000000-0000-0000-0000-000000000046', 'Prompt antibiotic therapy (benzylpenicillin or a third-generation cephalosporin such as ceftriaxone) improves outcomes in leptospirosis and should not be delayed while awaiting serological confirmation in a compatible clinical picture.', 2),
('d7000000-0000-0000-0000-000000000046', 'Severe leptospirosis can require renal replacement therapy and intensive supportive care; a broad differential (including malaria and dengue) should be considered and actively excluded in any returning febrile traveller with a relevant exposure history.', 3),
('d7000000-0000-0000-0000-000000000047', 'Amoebic liver abscess is primarily treated medically with a tissue-active nitroimidazole (metronidazole or tinidazole), usually avoiding the need for aspiration or surgical drainage.', 1),
('d7000000-0000-0000-0000-000000000047', 'A luminal agent (e.g. paromomycin, diloxanide furoate) should follow tissue-active treatment to eradicate intestinal colonisation and prevent recurrence/transmission, even when stool testing is negative, as this does not reliably exclude colonisation.', 2),
('d7000000-0000-0000-0000-000000000047', 'Aspiration/drainage of an amoebic liver abscess is reserved for specific situations: large abscesses at risk of rupture, left-lobe abscesses (risk of pericardial extension), diagnostic uncertainty (e.g. cannot exclude pyogenic abscess), or failure to respond to medical therapy.', 3),
('d7000000-0000-0000-0000-000000000048', 'Visceral leishmaniasis (kala-azar), caused by Leishmania donovani/infantum, classically presents with chronic fever, marked hepatosplenomegaly and pancytopenia, and is diagnosed by identifying intracellular amastigotes in bone marrow, splenic or lymph node aspirate.', 1),
('d7000000-0000-0000-0000-000000000048', 'Liposomal amphotericin B is an effective, well-tolerated first-line treatment for visceral leishmaniasis, particularly favoured over pentavalent antimonials in many settings due to its superior safety profile.', 2),
('d7000000-0000-0000-0000-000000000048', 'Visceral leishmaniasis is endemic in parts of the Indian subcontinent, East Africa, and the Mediterranean/Latin America, and should be considered in patients with a relevant travel/residence history presenting with unexplained splenomegaly, fever and cytopenias.', 3),
('d7000000-0000-0000-0000-000000000049', 'Strongyloides stercoralis causes chronic autoinfection that can persist asymptomatically for decades; corticosteroids and other immunosuppressive therapy can precipitate life-threatening hyperinfection syndrome or disseminated disease.', 1),
('d7000000-0000-0000-0000-000000000049', 'Any patient from or with prolonged residence in an endemic area who requires immunosuppressive therapy (especially corticosteroids) should be screened for Strongyloides (serology plus stool examination) and treated with ivermectin if positive, before or alongside starting immunosuppression.', 2),
('d7000000-0000-0000-0000-000000000049', 'Unexplained eosinophilia in a returning traveller or long-term resident of an endemic area should prompt specific consideration of helminth infections, including Strongyloides, rather than being dismissed as non-specific, particularly before immunosuppressive treatment.', 3),
('d7000000-0000-0000-0000-000000000050', 'Viral haemorrhagic fevers (e.g. Lassa fever, Ebola, Marburg) should be considered in any returning traveller with fever and bleeding/haemodynamic compromise who has a relevant exposure history (endemic area travel, contact with unwell individuals or bodily fluids) within the incubation period.', 1),
('d7000000-0000-0000-0000-000000000050', 'Suspected viral haemorrhagic fever requires immediate strict isolation, minimisation of unnecessary investigations/staff exposure, and urgent involvement of public health authorities and specialist high-consequence infectious disease services before further routine assessment proceeds.', 2),
('d7000000-0000-0000-0000-000000000050', 'Malaria remains an important differential (and can co-exist) in any returning febrile traveller and should still be tested for, but a negative malaria film does not exclude other serious travel-related diagnoses, including viral haemorrhagic fever.', 3);
